def generate_stats_from_T1(T1, min_value=0, max_value=100):
    """
    Convert elements in T1 to integers, create a list of random integers whose
    length is the sum of those integers, and return the mean, median, and mode.

    Uses the `random_int_stats` library when available for generation and/or
    statistics; falls back to Python standard library functions if needed.

    Args:
        T1: iterable of values convertible to int (e.g. list of strings or ints).
        min_value: minimum random integer (inclusive).
        max_value: maximum random integer (inclusive).

    Returns:
        dict with keys 'mean', 'median', 'mode'. 'mode' may be a single value
        or a list if there are multiple modes.
    """
    import random_int_stats
    from statistics import mean as _mean, median as _median, mode as _mode, multimode as _multimode, StatisticsError
    import random

    # Convert elements to integers
    try:
        ints = [int(x) for x in T1]
    except Exception as e:
        raise ValueError("All elements of T1 must be convertible to int") from e

    total = sum(ints)
    if total <= 0:
        raise ValueError("Sum of T1 must be a positive integer to generate a non-empty list")

    # Try to find a generator function in random_int_stats; otherwise fallback to random.randint
    gen_func = None
    for candidate in ('random_integers', 'random_ints', 'randints', 'generate_integers', 'generate', 'randint_list', 'random_integers_list'):
        if hasattr(random_int_stats, candidate):
            gen_func = getattr(random_int_stats, candidate)
            break

    if gen_func is not None:
        # Try a few common call signatures
        try:
            nums = list(gen_func(total, min_value, max_value))
        except TypeError:
            try:
                nums = list(gen_func(total, low=min_value, high=max_value))
            except TypeError:
                try:
                    nums = list(gen_func(total))
                except Exception as e:
                    # fallback
                    nums = [random.randint(min_value, max_value) for _ in range(total)]
    else:
        nums = [random.randint(min_value, max_value) for _ in range(total)]

    # Compute statistics, prefer random_int_stats functions if they exist
    # Mean
    if hasattr(random_int_stats, 'mean'):
        try:
            mean_val = random_int_stats.mean(nums)
        except Exception:
            mean_val = _mean(nums)
    else:
        mean_val = _mean(nums)

    # Median
    if hasattr(random_int_stats, 'median'):
        try:
            median_val = random_int_stats.median(nums)
        except Exception:
            median_val = _median(nums)
    else:
        median_val = _median(nums)

    # Mode: prefer a single value if unambiguous, otherwise return list of modes
    mode_val = None
    if hasattr(random_int_stats, 'mode'):
        try:
            mode_val = random_int_stats.mode(nums)
        except Exception:
            # try multimode or fallback
            if hasattr(random_int_stats, 'multimode'):
                try:
                    mode_val = random_int_stats.multimode(nums)
                except Exception:
                    try:
                        mode_val = _mode(nums)
                    except StatisticsError:
                        mode_val = _multimode(nums)
            else:
                try:
                    mode_val = _mode(nums)
                except StatisticsError:
                    mode_val = _multimode(nums)
    else:
        try:
            mode_val = _mode(nums)
        except StatisticsError:
            mode_val = _multimode(nums)

    return {'mean': mean_val, 'median': median_val, 'mode': mode_val}
