import random
import random_percentiles as rp
from typing import Tuple, Iterable, List, Any

def compute_percentiles(T1: Tuple[Tuple[str, ...], ...]) -> Tuple[float, float, float]:
    """
    Convert string integers in T1 (a tuple of tuples of strings) to ints, sum them,
    generate that many random integers in the range 0..100, and return the 25th,
    50th and 75th percentiles computed via the random_percentiles library.

    Args:
        T1: tuple of tuples containing string representations of integers,
            e.g. (("1","2"), ("3",))

    Returns:
        A tuple (p25, p50, p75) of percentiles as floats.

    Raises:
        ValueError: if the sum of integers is not a positive integer.
        ImportError / AttributeError: if the random_percentiles API cannot be used.
    """
    # convert strings to ints and sum
    try:
        ints: List[int] = [int(s) for group in T1 for s in group]
    except Exception as e:
        raise ValueError(f"T1 must contain string integers: {e}")
    total = sum(ints)
    if total <= 0:
        raise ValueError("Sum of integers must be positive to generate a random list.")

    # create list of random integers (range 0..100)
    data = [random.randint(0, 100) for _ in range(total)]

    # Try common APIs of the random_percentiles library
    get_result = None
    # common function names that libraries use (try them in order)
    for fname in ("percentile", "percentiles", "get_percentiles", "compute_percentiles"):
        func = getattr(rp, fname, None)
        if callable(func):
            # call with (data, [25,50,75]) which is a typical signature
            try:
                get_result = func(data, [25, 50, 75])
                break
            except TypeError:
                # maybe signature is (data, q) where q is a single int; skip
                continue
    if get_result is None:
        raise AttributeError("random_percentiles library available but expected percentile API not found.")

    # Normalize the result into a (p25, p50, p75) tuple of floats
    # handle a few common return formats: list/tuple/np.ndarray, dict, single value
    def _as_tuple(res: Any) -> Tuple[float, float, float]:
        if isinstance(res, (list, tuple)):
            if len(res) >= 3:
                return float(res[0]), float(res[1]), float(res[2])
            raise ValueError("percentile function returned a sequence with fewer than 3 values.")
        if hasattr(res, "tolist"):  # e.g., numpy array
            lst = res.tolist()
            if len(lst) >= 3:
                return float(lst[0]), float(lst[1]), float(lst[2])
        if isinstance(res, dict):
            # try numeric keys first, then string keys
            for keys in ((25,50,75), ("25","50","75")):
                try:
                    return float(res[keys[0]]), float(res[keys[1]]), float(res[keys[2]])
                except Exception:
                    pass
        # If the function returned a single value for each requested percentile (unlikely here),
        # fall back to raising an error.
        raise ValueError("Unable to interpret percentiles result from random_percentiles library.")

    return _as_tuple(get_result)
