from typing import Optional
import first_tag_scraper


def scrape_first_tag_text(url: str, tag: str, timeout: int = 10) -> Optional[str]:
    """
    Scrape the given URL for the first occurrence of the specified HTML tag and return its text content.

    This function uses the first_tag_scraper library. Because different versions of that library
    may expose different APIs, the function tries several common entry points:
      - first_tag_scraper.get_first_tag_text(url, tag, timeout=...)
      - first_tag_scraper.scrape_first_tag(url, tag, timeout=...)
      - first_tag_scraper.FirstTagScraper(...).get_text(url, tag)
      - first_tag_scraper.FirstTagScraper(...).scrape(url, tag)

    Parameters:
    - url: str -- the page URL to fetch (must include scheme, e.g. "https://example.com")
    - tag: str -- the HTML tag name to search for (e.g. "h1", "p", "title")
    - timeout: int -- optional timeout in seconds for network operations (default 10)

    Returns:
    - The text content of the first matching tag as a string, with surrounding whitespace stripped,
      or None if no such tag is found.

    Raises:
    - ValueError for invalid input (empty url or tag).
    - RuntimeError if the first_tag_scraper module does not provide a recognized API.
    - Any exceptions propagated from the underlying library (network, parsing, etc.)
    """
    # Basic validation
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    if not isinstance(tag, str) or not tag.strip():
        raise ValueError("tag must be a non-empty string")

    # Try common function entry points
    api_calls = [
        ("get_first_tag_text", lambda fn: fn(url, tag, timeout=timeout)),
        ("scrape_first_tag", lambda fn: fn(url, tag, timeout=timeout)),
    ]

    for name, call in api_calls:
        fn = getattr(first_tag_scraper, name, None)
        if callable(fn):
            result = call(fn)
            # Accept either a raw string or an object with a .text attribute
            if result is None:
                return None
            if isinstance(result, str):
                return result.strip()
            text = getattr(result, "text", None)
            if isinstance(text, str):
                return text.strip()
            # If result is something else, convert to str
            return str(result).strip()

    # Try common class-based entry points
    Cls = getattr(first_tag_scraper, "FirstTagScraper", None)
    if Cls is not None:
        try:
            scraper = Cls(timeout=timeout)
        except TypeError:
            # Fallback to no-arg constructor
            scraper = Cls()
        # try methods on instance
        instance_calls = [
            ("get_text", lambda m: m(url, tag)),
            ("scrape", lambda m: m(url, tag)),
        ]
        for mname, caller in instance_calls:
            meth = getattr(scraper, mname, None)
            if callable(meth):
                result = caller(meth)
                if result is None:
                    return None
                if isinstance(result, str):
                    return result.strip()
                text = getattr(result, "text", None)
                if isinstance(text, str):
                    return text.strip()
                return str(result).strip()

    # If we reach here, library didn't expose a known API
    raise RuntimeError(
        "first_tag_scraper module does not expose a recognized API. "
        "Expected functions like get_first_tag_text/scrape_first_tag or a FirstTagScraper class."
    )

# Example usage:
# text = scrape_first_tag_text("https://example.com", "h1")
# print("First H1 text:", text)
