            decoded_digest = base64.b64decode(password_b64)
        except Exception:
            return Response(400, b'Bad request.')

    # If library verify was used, rely on that result
    if verified is True:
        return Response(200, b'Login successful.')
    if verified is False:
        return Response(401, b'Login failed.')

    # Ensure decoded_digest is bytes
