        lambda: ny_temp_plotter.get_daytime_temperatures(start, end),
        lambda: ny_temp_plotter.fetch_daytime_temperatures('New York', start, end),
        lambda: ny_temp_plotter.get_daily_temperatures('New York', start, end),
        lambda: ny_temp_plotter.fetch_daily_temperatures('New York', start, end),
    ):
        try:
            temps_raw = fn_call()
            break
        except AttributeError as e:
            tried.append(e)
            continue

    if temps_raw is None:
        raise RuntimeError("Could not call a known function from ny_temp_plotter. "
                           "Tried several common names.")

    # Normalize fetched data into parallel lists: dates (datetime.date) and temps (floats)
    dates = []
    temps = []

    # If pandas Series or DataFrame
    if pd is not None and isinstance(temps_raw, (pd.Series, pd.DataFrame)):
        if isinstance(temps_raw, pd.Series):
            series = temps_raw
        else:
            # If DataFrame, try to use a 'temperature' column or the first numeric column
            if 'temperature' in temps_raw.columns:
                series = temps_raw['temperature']
            else:
                # choose first numeric column
                numeric_cols = temps_raw.select_dtypes(include=['number']).columns
                if len(numeric_cols) == 0:
                    raise ValueError("Pandas DataFrame returned with no numeric temperature column.")
                series = temps_raw[numeric_cols[0]]
        # index might be dates or there may be a date column
        if isinstance(series.index.dtype, (pd.core.dtypes.dtypes.DatetimeTZDtype,)) or pd.api.types.is_datetime64_any_dtype(series.index):
            idx = pd.to_datetime(series.index).to_pydatetime()
            dates = [d.date() for d in idx]
            temps = list(series.values)
        elif 'date' in series.index.names or 'Date' in series.index.names:
            idx = pd.to_datetime(series.index).to_pydatetime()
            dates = [d.date() for d in idx]
            temps = list(series.values)
        else:
            # look for a 'date'/'Date' column
            if 'date' in temps_raw.columns or 'Date' in temps_raw.columns:
                col = 'date' if 'date' in temps_raw.columns else 'Date'
                idx = pd.to_datetime(temps_raw[col]).to_pydatetime()
                dates = [d.date() for d in idx]
                # pick temperature values from series or first numeric column
                temps = list(series.values)
            else:
                # fallback: if length matches, use index positions as dates (not ideal)
                raise ValueError("Unable to interpret pandas output from ny_temp_plotter. "
                                 "Expected a datetime index or a 'date' column.")
    # If dict {date: temp}
    elif isinstance(temps_raw, dict):
        for k, v in sorted(temps_raw.items()):
            if isinstance(k, str):
                d = datetime.datetime.strptime(k, "%Y-%m-%d").date()
            elif isinstance(k, datetime.datetime):
                d = k.date()
            elif isinstance(k, datetime.date):
                d = k
            else:
                raise ValueError("Unrecognized date key type in returned dict.")
            dates.append(d)
            temps.append(float(v))
    # If list/tuple
    elif isinstance(temps_raw, (list, tuple)):
        # Could be list of (date, temp) pairs or two lists [dates, temps]
        if len(temps_raw) == 2 and all(isinstance(x, (list, tuple)) for x in temps_raw):
            # treat as (dates, temps)
            dlist, tlist = temps_raw
            for d, t in zip(dlist, tlist):
                if isinstance(d, str):
                    d_parsed = datetime.datetime.strptime(d, "%Y-%m-%d").date()
                elif isinstance(d, datetime.datetime):
                    d_parsed = d.date()
                elif isinstance(d, datetime.date):
                    d_parsed = d
                else:
                    raise ValueError("Unrecognized date type in list of dates.")
                dates.append(d_parsed)
                temps.append(float(t))
        else:
            # treat as iterable of pairs
            try:
                for item in temps_raw:
                    if isinstance(item, (list, tuple)) and len(item) >= 2:
                        d, t = item[0], item[1]
                        if isinstance(d, str):
                            d_parsed = datetime.datetime.strptime(d, "%Y-%m-%d").date()
                        elif isinstance(d, datetime.datetime):
                            d_parsed = d.date()
                        elif isinstance(d, datetime.date):
                            d_parsed = d
                        else:
                            raise ValueError("Unrecognized date type in returned sequence.")
                        dates.append(d_parsed)
                        temps.append(float(t))
                    else:
                        raise ValueError("List/tuple return value not in expected format.")
            except TypeError:
                raise ValueError("Unrecognized return type from ny_temp_plotter.")
    else:
        raise ValueError("Unrecognized return type from ny_temp_plotter.")

    if not dates:
        raise ValueError("No data returned for the specified date range.")

    # Sort by date just in case
    combined = sorted(zip(dates, temps), key=lambda x: x[0])
    dates, temps = zip(*combined)

    # Plot with Arial font
    plt.rcParams['font.family'] = 'Arial'
    fig, ax = plt.subplots(figsize=(10, 5))
    ax.plot(dates, temps, marker='o', linestyle='-')
    ax.set_xlabel('Date')
    ax.set_ylabel('Temperature (°C)')
    ax.set_title('Daily Temperatures in New York')

    # Format x-axis for dates
    ax.xaxis.set_major_locator(mdates.AutoDateLocator())
    ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y-%m-%d'))
    fig.autofmt_xdate()

    ax.grid(True, linestyle='--', alpha=0.4)

    if show:
        plt.show()

    return fig
