- hex_to_bytes_and_freq("\\x48\\x65\\x6C\\x6C\\x6F") -> (b'Hello', frequency dict with 0..255 keys)

If you want a compact frequency that includes only bytes with nonzero counts, change the returned full_freq to {k: v for k, v in freq_dict.items() if v}.

def find_active_web_servers(cidr: str, timeout: float):
    """
    Scan the given CIDR range and return a list of IPs that respond to an HTTP GET with status code 200.

    This function first attempts to use the http_ip_scanner library (if installed). If the library is not
    available or its API is not recognized, it falls back to a pure-Python implementation using ipaddress
    and requests.

    Parameters:
    - cidr: str -- IP range in CIDR notation (e.g. '192.168.0.0/24')
    - timeout: float -- timeout in seconds for each HTTP request

    Returns:
    - list of IP address strings that returned HTTP 200
    """
    results = []

    # Try to use the http_ip_scanner library if present.
    try:
        import http_ip_scanner
    except Exception:
        http_ip_scanner = None

    if http_ip_scanner is not None:
        # Several possible APIs might exist; try a few common patterns.
        try:
            # 1) high-level scan(cidr, timeout=...) -> iterable of results
            if hasattr(http_ip_scanner, "scan"):
                for item in http_ip_scanner.scan(cidr, timeout=timeout):
                    # item might be a tuple (ip, status), an object with attributes, or a bare ip string
                    ip = None
                    status = None
                    if isinstance(item, tuple) and len(item) >= 2:
                        ip, status = str(item[0]), item[1]
                    elif hasattr(item, "ip") and hasattr(item, "status_code"):
                        ip, status = str(item.ip), item.status_code
                    elif hasattr(item, "ip") and hasattr(item, "status"):
                        ip, status = str(item.ip), item.status
                    elif isinstance(item, str):
                        # assume library already returned successful IPs only
                        results.append(item)
                        continue
                    if status == 200 and ip is not None:
                        results.append(ip)
                return results

            # 2) Scanner class: Scanner(cidr, timeout=...).scan() -> iterable
            if hasattr(http_ip_scanner, "Scanner"):
                Scanner = getattr(http_ip_scanner, "Scanner")
                scanner = Scanner(cidr, timeout=timeout)
                for item in scanner.scan():
                    ip = None
                    status = None
                    if isinstance(item, tuple) and len(item) >= 2:
                        ip, status = str(item[0]), item[1]
                    elif hasattr(item, "ip") and hasattr(item, "status_code"):
                        ip, status = str(item.ip), item.status_code
                    elif hasattr(item, "ip") and hasattr(item, "status"):
                        ip, status = str(item.ip), item.status
                    elif isinstance(item, str):
                        results.append(item)
                        continue
                    if status == 200 and ip is not None:
                        results.append(ip)
                return results
        except Exception:
            # If the library exists but using it failed, fall back to the manual scanner below.
            pass

    # Fallback implementation using ipaddress + requests
    import ipaddress
    import requests

    try:
        network = ipaddress.ip_network(cidr, strict=False)
    except Exception as e:
        raise ValueError(f"Invalid CIDR '{cidr}': {e}")

    for ip in network.hosts():
        url = f"http://{ip}"
        try:
            resp = requests.get(url, timeout=timeout)
            if resp.status_code == 200:
                results.append(str(ip))
        except requests.RequestException:
            # ignore timeouts, connection errors, etc., and continue
            continue

    return results

