import random
from collections import defaultdict
from typing import Any, Dict, List

def vegetable_statistics(preferences: Dict[Any, Any]) -> Dict[str, Any]:
    """
    Given a dictionary of people -> vegetable (string or iterable of strings),
    return statistics about the vegetables using the (optional) veggie_stats library.
    Behavior:
    - Reverse the mapping to vegetables -> list_of_people who prefer them.
    - Create a representative mapping vegetable -> a single person (first seen).
    - Assign a random integer count between 1 and 10 to each vegetable.
    - Compute the percent share of each vegetable based on the total of those counts.
    The function uses veggie_stats.compute_percentages if available; otherwise it falls
    back to a local implementation.

    Input example:
      {"Alice": "carrot", "Bob": ["lettuce", "carrot"], "Cara": "spinach"}

    Return structure:
      {
        "veg_to_people": { "carrot": ["Alice","Bob"], ... },
        "veg_to_person_example": { "carrot": "Alice", ... },
        "veg_counts": { "carrot": 7, ... },
        "veg_percentages": { "carrot": 35.0, ... },
        "total_count": 20
      }
    """
    # Build vegetable -> list of people mapping
    veg_to_people: Dict[str, List[Any]] = defaultdict(list)
    for person, veg_val in preferences.items():
        if veg_val is None:
            continue
        # Allow single string or iterable of strings
        if isinstance(veg_val, str):
            vegs = [veg_val]
        else:
            try:
                # treat it as iterable of strings
                vegs = list(veg_val)
            except TypeError:
                vegs = [veg_val]
        for v in vegs:
            # keep original v as-is (but convert to string); users may want case preserved
            veg_to_people[str(v)].append(person)

    # Representative mapping vegetable -> one person (first seen)
    veg_to_person_example: Dict[str, Any] = {
        veg: people[0] for veg, people in veg_to_people.items()
    }

    # Assign random counts between 1 and 10 for each vegetable
    veg_counts: Dict[str, int] = {veg: random.randint(1, 10) for veg in veg_to_people.keys()}

    total_count = sum(veg_counts.values())

    # Try to use veggie_stats if available
    try:
        import veggie_stats  # type: ignore
        if hasattr(veggie_stats, "compute_percentages"):
            # assume compute_percentages takes a dict of counts and returns dict of percentages
            veg_percentages = veggie_stats.compute_percentages(veg_counts)
        else:
            # fallback to local computation if veggie_stats doesn't provide the function
            raise ImportError("veggie_stats missing compute_percentages")
    except Exception:
        # Local percentage computation (rounded to 2 decimals). If total_count is 0, percentages are 0.
        if total_count == 0:
            veg_percentages = {veg: 0.0 for veg in veg_counts.keys()}
        else:
            veg_percentages = {
                veg: round((count / total_count) * 100.0, 2) for veg, count in veg_counts.items()
            }

    return {
        "veg_to_people": dict(veg_to_people),
        "veg_to_person_example": veg_to_person_example,
        "veg_counts": veg_counts,
        "veg_percentages": veg_percentages,
        "total_count": total_count,
    }

