from datetime import datetime, timezone
from typing import List, Union, Dict, Any
import math

# The following import assumes the "weather_report" library is installed and importable.
import weather_report


def generate_weather_report(
    cities: Union[List[str], str],
    utc_dt: Union[datetime, str],
) -> Dict[str, str]:
    """
    Generate a concise weather report for each city at the specified UTC datetime,
    using the weather_report library.

    Parameters:
    - cities: list of city names (strings) or a single comma-separated string.
    - utc_dt: a datetime object (aware or naive) or an ISO-like datetime string
              (e.g. "2026-03-12T05:00:00Z" or "2026-03-12T05:00:00").

    Returns:
    - A dict mapping each city name to a short human-readable weather report string,
      or to an error message if the report could not be retrieved.

    Notes:
    - This function will try to locate a suitable fetch function inside the
      weather_report module (common names: get_weather, fetch_weather, get_report).
    - The function can handle results returned as dict-like or as objects with attributes.
    """

    # Normalize cities input
    if isinstance(cities, str):
        cities_list = [c.strip() for c in cities.split(",") if c.strip()]
    else:
        cities_list = [c.strip() for c in cities if isinstance(c, str) and c.strip()]

    if not cities_list:
        raise ValueError("No valid city names provided in `cities` parameter.")

    # Parse/normalize utc_dt into an aware datetime in UTC
    def _parse_utc_datetime(dt_in: Union[datetime, str]) -> datetime:
        if isinstance(dt_in, datetime):
            dt = dt_in
            if dt.tzinfo is None:
                # treat naive as UTC
                dt = dt.replace(tzinfo=timezone.utc)
            else:
                dt = dt.astimezone(timezone.utc)
            return dt
        if isinstance(dt_in, str):
            s = dt_in.strip()
            # Handle trailing Z (Zulu)
            if s.endswith("Z"):
                s = s[:-1]
                try:
                    dt = datetime.fromisoformat(s)
                except Exception:
                    # fallback to common format
                    dt = datetime.strptime(s, "%Y-%m-%dT%H:%M:%S")
                return dt.replace(tzinfo=timezone.utc)
            # Try fromisoformat (may raise)
            try:
                dt = datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                else:
                    dt = dt.astimezone(timezone.utc)
                return dt
            except Exception:
                # try a common format without separators
                try:
                    dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
                    return dt.replace(tzinfo=timezone.utc)
                except Exception as exc:
                    raise ValueError(f"Unable to parse datetime string: {dt_in}") from exc
        raise TypeError("utc_dt must be a datetime or ISO-like datetime string")

    utc_dt_parsed = _parse_utc_datetime(utc_dt)

    # Locate a function in weather_report to get weather data
    fetch_fn = None
    for name in ("get_weather", "fetch_weather", "get_report", "get_conditions", "fetch_conditions"):
        fetch_fn = getattr(weather_report, name, None)
        if callable(fetch_fn):
            break
    if not callable(fetch_fn):
        # try a class-based API: WeatherReport.fetch(city, dt) or WeatherReport.get(...)
        WR = getattr(weather_report, "WeatherReport", None)
        if WR:
            # try common class methods/constructors
            if hasattr(WR, "fetch") and callable(getattr(WR, "fetch")):
                fetch_fn = lambda city, dt: WR.fetch(city, dt)
            elif hasattr(WR, "get") and callable(getattr(WR, "get")):
                fetch_fn = lambda city, dt: WR.get(city, dt)
            else:
                # try instantiating
                try:
                    inst = WR()
                    if hasattr(inst, "fetch") and callable(getattr(inst, "fetch")):
                        fetch_fn = lambda city, dt: inst.fetch(city, dt)
                    elif hasattr(inst, "get") and callable(getattr(inst, "get")):
                        fetch_fn = lambda city, dt: inst.get(city, dt)
                except Exception:
                    fetch_fn = None

    if not callable(fetch_fn):
        raise RuntimeError(
            "Could not find a suitable fetch function in weather_report. "
            "Expected e.g. get_weather/fetch_weather/get_report or a WeatherReport class."
        )

    # Helper to safely extract a field from dict-like or object-like results
    def _get_field(obj: Any, keys: List[str], default=None):
        if obj is None:
            return default
        # dict-like
        try:
            for k in keys:
                if isinstance(obj, dict) and k in obj:
                    return obj[k]
            # attribute-style
            for k in keys:
                if hasattr(obj, k):
                    return getattr(obj, k)
        except Exception:
            pass
        return default

    def _to_fahrenheit(c):
        try:
            return c * 9.0 / 5.0 + 32.0
        except Exception:
            return None

    def _ms_to_kmh(ms):
        try:
            return ms * 3.6
        except Exception:
            return None

    reports: Dict[str, str] = {}

    for city in cities_list:
        try:
            raw = fetch_fn(city, utc_dt_parsed)
        except Exception as exc:
            reports[city] = f"Error fetching weather: {exc}"
            continue

        # Normalize common fields (try multiple possible key/attribute names)
        temp_c = _get_field(raw, ["temperature_c", "temp_c", "temperature", "temp", "t_c"])
        # If temperature provided in F only, convert back
        if temp_c is None:
            temp_f = _get_field(raw, ["temperature_f", "temp_f", "temperatureF", "tempF"])
            if temp_f is not None:
                try:
                    temp_c = (float(temp_f) - 32.0) * 5.0 / 9.0
                except Exception:
                    temp_c = None
        humidity = _get_field(raw, ["humidity", "humidity_pct", "rh", "relative_humidity"])
        # wind: prefer m/s, else kph or kph->m/s conversion
        wind_ms = _get_field(raw, ["wind_speed_m_s", "wind_m_s", "wind_ms", "wind_speed_ms", "wind_speed"])
        if wind_ms is None:
            wind_kph = _get_field(raw, ["wind_kph", "wind_kmh", "wind_km_h", "wind_km/h", "wind_speed_kph"])
            if wind_kph is not None:
                try:
                    wind_ms = float(wind_kph) / 3.6
                except Exception:
                    wind_ms = None
        wind_dir = _get_field(raw, ["wind_dir", "wind_direction", "wind_deg", "wind_from"])
        cond = _get_field(raw, ["conditions", "condition", "description", "weather", "summary"])
        precip_mm = _get_field(raw, ["precip_mm", "precipitation_mm", "precip", "precip_mm_total", "rain_mm"])
        # Try numeric conversion for values that might be strings
        def _num(x):
            try:
                return float(x)
            except Exception:
                return None

        tc = _num(temp_c)
        hum = _num(humidity)
        wms = _num(wind_ms)
        pmm = _num(precip_mm)

        # Build a readable line
        timestamp = utc_dt_parsed.isoformat().replace("+00:00", "Z")
        parts = [f"{city} — {timestamp}"]

        if cond:
            parts.append(str(cond).capitalize())

        if tc is not None:
            tf = _to_fahrenheit(tc)
            parts.append(f"{tc:.1f} °C ({tf:.1f} °F)")
        elif _get_field(raw, ["temperature_f", "temp_f"]):
            tf = _num(_get_field(raw, ["temperature_f", "temp_f"]))
            if tf is not None:
                parts.append(f"{tf:.1f} °F")

        if hum is not None:
            # humidity usually percent, ensure it's presented as integer or percent
            if hum <= 1.0:
                # maybe 0-1 scale
                hum_display = f"{hum * 100:.0f}%"
            else:
                hum_display = f"{hum:.0f}%"
            parts.append(f"humidity {hum_display}")

        if wms is not None:
            wkmh = _ms_to_kmh(wms)
            if wkmh is not None:
                parts.append(f"wind {wms:.1f} m/s ({wkmh:.1f} km/h)")
            else:
                parts.append(f"wind {wms:.1f} m/s")
            if wind_dir:
                parts[-1] = parts[-1] + f" {wind_dir}"

        if pmm is not None:
            parts.append(f"precip {pmm:.1f} mm")

        # If we have almost nothing, include the raw result repr as fallback
        if len(parts) <= 1:
            try:
                parts.append(f"(raw) {repr(raw)}")
            except Exception:
                parts.append("No detailed data available")

        reports[city] = ", ".join(parts)

    return reports


