Here's a self-contained Python function that uses the random_image_viewer library to generate a random RGB image and display it. It tries common function names inside random_image_viewer and falls back to a local viewer (Pillow/matplotlib) if needed.

```python
def generate_and_view_random_rgb(width=256, height=256, show=True):
    """
    Generate a random RGB image using the random_image_viewer library and optionally view it.

    Parameters:
    - width (int): image width in pixels (default 256)
    - height (int): image height in pixels (default 256)
    - show (bool): whether to display the generated image (default True)

    Returns:
    - img: the generated image object (may be a numpy array or a PIL.Image.Image, depending on the library)

    Example:
    >>> img = generate_and_view_random_rgb(300, 200)
    """
    # Import the library (raise helpful error if missing)
    try:
        import random_image_viewer
    except ImportError as exc:
        raise ImportError(
            "The package 'random_image_viewer' is required but not installed. "
            "Install it with e.g. `pip install random_image_viewer` and try again."
        ) from exc

    # Helper: try calling generator with a few common signatures
    def _call_generator(gen):
        # try several calling conventions
        try:
            return gen(width, height, mode="RGB")
        except TypeError:
            pass
        try:
            return gen((width, height), mode="RGB")
        except TypeError:
            pass
        try:
            return gen(width, height)
        except TypeError:
            pass
        try:
            return gen((width, height))
        except Exception as e:
            raise RuntimeError(f"Failed to call generator function {gen!r}: {e}") from e

    # Find a generator function in the module
    gen_candidates = [
        "generate_random_image", "generate", "random_image", "create_random_image",
        "rand_image", "random_rgb"
    ]
    generator = None
    for name in gen_candidates:
        if hasattr(random_image_viewer, name):
            generator = getattr(random_image_viewer, name)
            break
    if generator is None:
        raise RuntimeError(
            "Could not find a generator function in random_image_viewer. "
            "Expected one of: " + ", ".join(gen_candidates)
        )

    # Generate the image
    img = _call_generator(generator)

    # Helper: fallback viewer using Pillow/matplotlib
    def _fallback_show(image):
        try:
            from PIL import Image
        except Exception:
            Image = None
        try:
            import numpy as np
        except Exception:
            np = None
        try:
            import matplotlib.pyplot as plt
        except Exception:
            plt = None

        # If it's a PIL Image, use its show() (quick, opens default image viewer)
        if Image is not None and isinstance(image, Image.Image):
            try:
                image.show()
                return
            except Exception:
                pass

        # If it's a numpy array or convertible, use matplotlib
        if plt is not None:
            try:
                # If it's a PIL Image, convert to array
                if Image is not None and isinstance(image, Image.Image):
                    arr = np.array(image) if np is not None else None
                else:
                    arr = image
                plt.figure(figsize=(6, 6 * height / width))
                plt.axis('off')
                plt.imshow(arr)
                plt.show()
                return
            except Exception:
                pass

        # Last resort: try calling a .show() attribute
        if hasattr(image, "show"):
            try:
                image.show()
                return
            except Exception:
                pass

        raise RuntimeError(
            "Unable to display the generated image. Install matplotlib and Pillow for fallback viewing."
        )

    # Display if requested
    if show:
        # Try to find a view function in the library
        view_candidates = ["view_image", "show", "display", "view", "imshow"]
        viewer = None
        for name in view_candidates:
            if hasattr(random_image_viewer, name):
                viewer = getattr(random_image_viewer, name)
                break
        if viewer is not None:
            try:
                # try calling with the image directly
                viewer(img)
            except Exception:
                # fallback if the library's viewer fails
                _fallback_show(img)
        else:
            _fallback_show(img)

    return img
