Here's a self-contained Python function that uses the mean_by_position library when available (and falls back to a local implementation if not). It computes the mean of numeric values for each position across the input list of sequences, returns a list of means (None where no numeric values exist for a position), and optionally writes the results to a JSON file.

```python
from typing import Iterable, List, Optional, Any
import json
import math

def compute_mean_by_position(data: Iterable[Iterable[Any]], json_path: Optional[str] = None) -> List[Optional[float]]:
    """
    Compute the mean of numeric values for each position across the provided sequences.

    Parameters:
    - data: an iterable of iterables (e.g., list of lists/tuples). Elements can be int/float or other types;
            non-numeric values are ignored.
    - json_path: optional path to a JSON file to write the result. The JSON will contain a list where each
                 element is either a number (float) or null (for positions with no numeric values).

    Returns:
    - A list of means (float) by position. Positions that have no numeric values are represented as None.
    """
    # First try to use the mean_by_position library if available
    try:
        # The library may expose different entry points; this is a common name.
        # If the library is installed and provides a compatible function, use it.
        from mean_by_position import mean_by_position as mbp_func  # type: ignore
        raw_result = mbp_func(data)
        # Ensure we return a plain Python list of floats/None
        result: List[Optional[float]] = []
        for v in list(raw_result):
            if v is None:
                result.append(None)
            else:
                # handle numpy/scalar types too
                try:
                    fv = float(v)
                    if math.isnan(fv):
                        result.append(None)
                    else:
                        result.append(fv)
                except Exception:
                    result.append(None)
    except Exception:
        # Fallback implementation if the library is unavailable or incompatible
        from collections import defaultdict
        sums = defaultdict(float)
        counts = defaultdict(int)
        maxlen = 0
        for row in data:
            if row is None:
                continue
            # treat row as an iterable of values
            try:
                iterator = iter(row)
            except TypeError:
                continue
            for idx, val in enumerate(row):
                maxlen = max(maxlen, idx + 1)
                # accept ints and floats, but reject booleans (bool is subclass of int)
                if isinstance(val, bool):
                    continue
                if isinstance(val, (int, float)):
                    # ignore NaN
                    try:
                        if isinstance(val, float) and math.isnan(val):
                            continue
                    except Exception:
                        pass
                    sums[idx] += float(val)
                    counts[idx] += 1
                else:
                    # try to coerce numeric-like strings
                    try:
                        fv = float(val)
                        if math.isnan(fv):
                            continue
                        sums[idx] += fv
                        counts[idx] += 1
                    except Exception:
                        continue
        result = []
        for i in range(maxlen):
            if counts.get(i, 0):
                result.append(sums[i] / counts[i])
            else:
                result.append(None)

    # Optionally write JSON (convert None to null, ensure floats are plain Python floats)
    if json_path is not None:
        serializable = [None if v is None else float(v) for v in result]
        with open(json_path, "w", encoding="utf-8") as f:
            json.dump(serializable, f, indent=2, allow_nan=False)

    return result
```

Example usage:
- compute_mean_by_position([[1, 2], [3, None], [5, 6]]) -> [3.0, 4.0]
- compute_mean_by_position(data, "means.json") -> writes results to means.json and returns the list

