def calculate_nested_stats(nested_list, size=5, seed=None):
    """
    Calculate mean, median, and mode for each sublist in nested_list.
    If a sublist is empty, it is filled with `size` random integers in [0, 100].
    Uses the `nested_list_stats` library for calculations when available, with
    fallbacks to Python's stdlib if needed.

    Parameters:
    - nested_list: list of lists (each inner list contains numeric values)
    - size: number of random integers to fill an empty sublist (default 5)
    - seed: optional integer seed for random number reproducibility

    Returns:
    - List of dicts, one per sublist, with keys:
      - "index": index of the sublist in the input
      - "values": the (possibly filled) list of values used
      - "mean": mean of values (float)
      - "median": median of values (float)
      - "mode": mode of values; a single value if unique mode, otherwise a list of modes
    """
    import random
    from collections import Counter

    if seed is not None:
        random.seed(seed)

    # Try to import nested_list_stats functions; they may not exist in some envs.
    try:
        import nested_list_stats as nls
        nls_mean = getattr(nls, "mean", None)
        nls_median = getattr(nls, "median", None)
        nls_mode = getattr(nls, "mode", None)
    except Exception:
        nls_mean = nls_median = nls_mode = None

    # stdlib fallbacks
    import statistics

    def _mean(values):
        if nls_mean:
            try:
                return float(nls_mean(values))
            except Exception:
                pass
        return float(statistics.mean(values))

    def _median(values):
        if nls_median:
            try:
                return float(nls_median(values))
            except Exception:
                pass
        return float(statistics.median(values))

    def _mode(values):
        # Prefer nested_list_stats if available
        if nls_mode:
            try:
                m = nls_mode(values)
                # If nested_list_stats returns multiple modes as iterable, normalize
                if isinstance(m, (list, tuple, set)):
                    m_list = list(m)
                    return m_list[0] if len(m_list) == 1 else m_list
                return m
            except Exception:
                pass
        # Fallback: use Counter to allow multimodal result
        ctr = Counter(values)
        if not ctr:
            return None
        max_count = max(ctr.values())
        modes = [val for val, cnt in ctr.items() if cnt == max_count]
        return modes[0] if len(modes) == 1 else modes

    results = []
    for idx, sub in enumerate(nested_list):
        if not sub:
            values = [random.randint(0, 100) for _ in range(size)]
        else:
            # Make a shallow copy to avoid mutating the caller's lists
            values = list(sub)

        # Ensure there is at least one numeric value (we filled empties above)
        if not values:
            raise ValueError(f"Sublist at index {idx} is empty and could not be filled.")

        mean_val = _mean(values)
        median_val = _median(values)
        mode_val = _mode(values)

        results.append({
            "index": idx,
            "values": values,
            "mean": mean_val,
            "median": median_val,
            "mode": mode_val
        })

    return results

