    # Clean up temporary file if created and not requested to keep
    if temp_file_created and not keep_dst:
        try:
            os.remove(dst_path)
        except Exception:
            # Not critical; the caller can handle leftover files if removal fails
            pass

    if temp_file_created and keep_dst:
        return contents, dst_path

    return contents

