    try:
        ax.hist(data_arr, bins=bins, density=density, color=color, alpha=alpha)
    except Exception as e:
        # If ax.hist is not available, try using a pyplot.hist fallback
        try:
            hplt.hist(data_arr, bins=bins, density=density, color=color, alpha=alpha, ax=ax)
        except Exception:
            raise RuntimeError("Could not plot histogram with histplotlib: " + str(e))

    if title:
        try:
            ax.set_title(title)
        except Exception:
            try:
                ax.title.set_text(title)
            except Exception:
                pass

    if xlabel:
        try:
            ax.set_xlabel(xlabel)
        except Exception:
            try:
                ax.xaxis.label.set_text(xlabel)
            except Exception:
                pass

    if ylabel:
        try:
            ax.set_ylabel(ylabel)
        except Exception:
            try:
                ax.yaxis.label.set_text(ylabel)
            except Exception:
                pass

    if grid:
        try:
            ax.grid(True, linestyle='--', alpha=0.5)
        except Exception:
            pass

    if show:
        # Use histplotlib's show if available
        try:
            hplt.show()
        except Exception:
            # If no show, try figure's show
            try:
                if fig is not None:
                    fig.show()
            except Exception:
                pass

    return fig, ax
