def fit_quadratic(x, y):
    """
    Fit a quadratic y = a*x^2 + b*x + c to the provided data using the
    `quadratic_fitter` library if available. Returns the fitted parameters
    and the fitted y-values evaluated at the input x.

    Parameters
    ----------
    x : array-like, shape (n,)
        Independent variable values.
    y : array-like, shape (n,)
        Dependent variable values.

    Returns
    -------
    params : dict
        Dictionary with keys 'a', 'b', 'c' containing the fitted coefficients
        for a*x^2 + b*x + c.
    y_fit : numpy.ndarray, shape (n,)
        Fitted y-values evaluated at the input x, in the same order as x.

    Notes
    -----
    - This function attempts to use the `quadratic_fitter` library if it is
      importable and exposes a fitting routine. If the library cannot be used
      (not installed or API incompatible), the function falls back to
      numpy.polyfit to perform the quadratic fit.
    - The function is defensive about different possible return types from the
      external library (e.g., tuple (params, y_fit), params array, or an
      object with attributes).

    Example
    -------
    >>> x = [0, 1, 2, 3]
    >>> y = [1, 3, 7, 13]
    >>> params, y_fit = fit_quadratic(x, y)
    >>> params
    {'a': 1.0, 'b': 1.0, 'c': 1.0}
    """
    import importlib
    import numpy as np

    x = np.asarray(x, dtype=float).ravel()
    y = np.asarray(y, dtype=float).ravel()
    if x.shape != y.shape:
        raise ValueError("x and y must have the same shape")

    qf = None
    try:
        qf = importlib.import_module("quadratic_fitter")
    except Exception:
        qf = None

    def _params_from_vector(vec):
        vec = np.asarray(vec, dtype=float).ravel()
        if vec.size != 3:
            raise ValueError("Expected a 3-element parameter vector (a, b, c)")
        return float(vec[0]), float(vec[1]), float(vec[2])

    a = b = c = None
    y_fit = None

    # Try to use the quadratic_fitter module if present
    if qf is not None:
        # Candidate call patterns to try, with defensive parsing of the result.
        tried = []
        # 1) function fit_quadratic(x, y)
        if hasattr(qf, "fit_quadratic") and callable(qf.fit_quadratic):
            try:
                res = qf.fit_quadratic(x, y)
                tried.append("fit_quadratic")
            except Exception:
                res = None
            if res is not None:
                # parse res
                if isinstance(res, tuple) and len(res) == 2:
                    p, yf = res
                    try:
                        a, b, c = _params_from_vector(p)
                        y_fit = np.asarray(yf, dtype=float)
                    except Exception:
                        pass
                else:
                    # maybe returns params vector
                    try:
                        a, b, c = _params_from_vector(res)
                    except Exception:
                        pass

        # 2) function fit(x, y)
        if a is None and hasattr(qf, "fit") and callable(qf.fit):
            try:
                res = qf.fit(x, y)
                tried.append("fit")
            except Exception:
                res = None
            if res is not None:
                if isinstance(res, tuple) and len(res) == 2:
                    p, yf = res
                    try:
                        a, b, c = _params_from_vector(p)
                        y_fit = np.asarray(yf, dtype=float)
                    except Exception:
                        pass
                else:
                    try:
                        a, b, c = _params_from_vector(res)
                    except Exception:
                        pass

        # 3) class QuadraticFitter with .fit or callable class
        if a is None and hasattr(qf, "QuadraticFitter"):
            try:
                cls = getattr(qf, "QuadraticFitter")
                # If it's a class, instantiate
                inst = None
                if callable(cls):
                    try:
                        inst = cls()
                    except Exception:
                        # maybe constructor takes x,y
                        try:
                            inst = cls(x, y)
                        except Exception:
                            inst = None
                if inst is not None:
                    # try .fit
                    if hasattr(inst, "fit") and callable(inst.fit):
                        try:
                            res = inst.fit(x, y)
                        except Exception:
                            res = None
                    else:
                        # maybe inst itself holds params as attributes
                        res = inst
                    if res is not None:
                        # parse object with attributes a,b,c or params
                        if hasattr(res, "a") and hasattr(res, "b") and hasattr(res, "c"):
                            a = float(getattr(res, "a"))
                            b = float(getattr(res, "b"))
                            c = float(getattr(res, "c"))
                        elif hasattr(res, "params"):
                            try:
                                a, b, c = _params_from_vector(res.params)
                            except Exception:
                                pass
                        elif isinstance(res, tuple) and len(res) == 2:
                            p, yf = res
                            try:
                                a, b, c = _params_from_vector(p)
                                y_fit = np.asarray(yf, dtype=float)
                            except Exception:
                                pass
                        else:
                            # maybe res is params vector
                            try:
                                a, b, c = _params_from_vector(res)
                            except Exception:
                                pass
            except Exception:
                pass

        # 4) other common names
        if a is None:
            for name in ("quadratic_fit", "fit_quadratic_curve", "fit_parabola"):
                if hasattr(qf, name) and callable(getattr(qf, name)):
                    try:
                        res = getattr(qf, name)(x, y)
                    except Exception:
                        res = None
                    if res is not None:
                        if isinstance(res, tuple) and len(res) == 2:
                            p, yf = res
                            try:
                                a, b, c = _params_from_vector(p)
                                y_fit = np.asarray(yf, dtype=float)
                                break
                            except Exception:
                                pass
                        else:
                            try:
                                a, b, c = _params_from_vector(res)
                                break
                            except Exception:
                                pass

    # If we have params now, compute y_fit if needed
    if a is not None and y_fit is None:
        y_fit = a * x ** 2 + b * x + c

    # Fall back to numpy.polyfit if we couldn't use the library successfully
    if a is None:
        # quadratic polynomial fit using numpy
        p = np.polyfit(x, y, 2)  # returns [a, b, c] for a*x^2 + b*x + c
        a, b, c = float(p[0]), float(p[1]), float(p[2])
        y_fit = a * x ** 2 + b * x + c

    params = {"a": a, "b": b, "c": c}
    return params, y_fit

def first_two_principal_components(X):
    """
    Perform PCA on array X using the pca_utils library and return the first two principal components.

    Args:
        X: array-like, shape (n_samples, n_features) or (n_samples,) for a single feature.

    Returns:
        tuple (scores, components)
        - scores: numpy array shape (n_samples, k) with the projected data onto the first k= min(2, n_features) PCs.
        - components: numpy array shape (k, n_features) with the principal component vectors (loadings).

    The function prefers pca_utils.PCA (or pca_utils.pca) if available; it falls back to sklearn or a manual SVD if needed.
    """
    import numpy as np
    X = np.asarray(X)
    if X.ndim == 1:
        X = X.reshape(-1, 1)
    n_samples, n_features = X.shape
    k = min(2, n_features)

    # Try to use pca_utils library preferentially
    try:
        import pca_utils
    except Exception:
        pca_utils = None

    # Helper: compute PCA via SVD (centering done here)
    def _svd_pca(Xarr, k):
        Xc = Xarr - Xarr.mean(axis=0)
        U, S, Vt = np.linalg.svd(Xc, full_matrices=False)
        # scores = U * S (broadcast S over columns)
        scores = U[:, :k] * S[:k]
        components = Vt[:k, :]
        return scores, components

    if pca_utils is not None:
        # Try class-like API: pca_utils.PCA
        if hasattr(pca_utils, "PCA"):
            try:
                PCA_cls = getattr(pca_utils, "PCA")
                try:
                    pca = PCA_cls(n_components=k)
                except TypeError:
                    pca = PCA_cls(k)
                # Prefer fit_transform if available
                if hasattr(pca, "fit_transform"):
                    scores = pca.fit_transform(X)
                else:
                    pca.fit(X)
                    scores = pca.transform(X)
                # try to read component vectors
                components = getattr(pca, "components_", None) or getattr(pca, "components", None)
                if components is None:
                    # fallback to SVD if components not exposed
                    return _svd_pca(X, k)
                scores = np.asarray(scores)[:, :k]
                components = np.asarray(components)[:k, :]
                return scores, components
            except Exception:
                pass
        # Try function-like API: pca_utils.pca(...)
        if hasattr(pca_utils, "pca"):
            try:
                # try common signatures
                try:
                    res = pca_utils.pca(X, n_components=k)
                except TypeError:
                    try:
                        res = pca_utils.pca(X, components=k)
                    except TypeError:
                        res = pca_utils.pca(X, k)
                # Interpret return
                if isinstance(res, tuple):
                    a = np.asarray(res[0])
                    b = np.asarray(res[1])
                    # determine which is scores by comparing first dimension to n_samples
                    if a.shape[0] == n_samples:
                        scores, components = a, b
                    elif b.shape[0] == n_samples:
                        scores, components = b, a
                    else:
                        # unknown ordering/shapes -> fallback to SVD
                        return _svd_pca(X, k)
                    scores = scores[:, :k]
                    components = components[:k, :]
                    return np.asarray(scores), np.asarray(components)
                else:
                    # maybe an object with attributes
                    obj = res
                    scores = getattr(obj, "scores", None) or getattr(obj, "X_pca", None) or None
                    components = getattr(obj, "components_", None) or getattr(obj, "components", None) or None
                    if scores is not None and components is not None:
                        return np.asarray(scores)[:, :k], np.asarray(components)[:k, :]
                    # fallback
                    return _svd_pca(X, k)
            except Exception:
                pass

    # Fallback: use sklearn if available
    try:
        from sklearn.decomposition import PCA as SKPCA
        sk = SKPCA(n_components=k)
        scores = sk.fit_transform(X)
        components = sk.components_
        return scores[:, :k], components[:k, :]
    except Exception:
        # Final fallback: manual SVD implementation
        return _svd_pca(X, k)

