def plot_average_scores(score_dicts, color='blue'):
    """
    Combine a list of student-score dictionaries, compute average score per student (ignoring None),
    validate scores (no negatives allowed), and return a matplotlib Figure containing a bar chart
    of average scores (students on x-axis, average score on y-axis).

    Uses student_score_aggregator if available (falls back to an internal implementation if the
    library doesn't provide a compatible helper).

    Parameters:
    - score_dicts: list of dict
        Each dict maps student-name (str) -> score (int/float or None). Dictionaries can have
        different sets of keys.
    - color: str
        Bar color, must be one of: 'red', 'yellow', 'green', 'blue', 'purple'.

    Returns:
    - matplotlib.figure.Figure: the figure containing the bar chart.

    Raises:
    - ValueError: if any score is negative, or color is invalid.
    - TypeError: if input types are not as expected (non-numeric non-None score).
    """
    # Allowed colors
    allowed_colors = {'red', 'yellow', 'green', 'blue', 'purple'}
    if color not in allowed_colors:
        raise ValueError(f"color must be one of {sorted(allowed_colors)}; got {color!r}")

    # Basic input validation
    if not isinstance(score_dicts, list):
        raise TypeError("score_dicts must be a list of dictionaries")

    # Try to import and (optionally) use student_score_aggregator
    try:
        import student_score_aggregator as ssa  # may be a no-op if library doesn't supply helpers
    except Exception:
        ssa = None  # we'll just fall back to our own implementation

    # If the aggregator library provides a convenience function, try to use it.
    # We conservatively look for a few plausible function names; otherwise do manual aggregation.
    combined = None
    if ssa is not None:
        for func_name in ('combine_scores', 'combine', 'aggregate_scores', 'aggregate'):
            fn = getattr(ssa, func_name, None)
            if callable(fn):
                try:
                    combined = fn(score_dicts)
                except Exception:
                    # If the library helper exists but errors for some reason, ignore and fallback
                    combined = None
                break

    # Manual aggregation fallback (or primary if library wasn't helpful)
    if combined is None:
        totals = {}
        counts = {}
        for idx, d in enumerate(score_dicts):
            if not isinstance(d, dict):
                raise TypeError(f"Element at index {idx} of score_dicts is not a dict")
            for student, score in d.items():
                # ignore None values
                if score is None:
                    continue
                # numeric check
                if not isinstance(score, (int, float)):
                    raise TypeError(f"Score for student {student!r} is not numeric: {score!r}")
                # negative check
                if score < 0:
                    raise ValueError(f"Negative score encountered for student {student!r}: {score}")
                totals[student] = totals.get(student, 0) + score
                counts[student] = counts.get(student, 0) + 1
        # Build combined mapping as totals (sums) if needed by library-style interface
        combined = {}
        for student in totals:
            combined[student] = {
                'total': totals[student],
                'count': counts[student]
            }

    # Now compute averages from the 'combined' structure.
    # Accept two possible shapes:
    # 1) combined is a dict student -> numeric average
    # 2) combined is a dict student -> { 'total': X, 'count': N } (our fallback)
    averages = {}
    if isinstance(combined, dict):
        # detect numeric averages directly
        all_numeric = all(isinstance(v, (int, float)) for v in combined.values())
        if all_numeric:
            for student, avg in combined.items():
                if avg is None:
                    continue
                if avg < 0:
                    raise ValueError(f"Negative average for student {student!r}: {avg}")
                averages[student] = float(avg)
        else:
            # assume structure like {'student': {'total': X, 'count': N}}
            for student, info in combined.items():
                if info is None:
                    continue
                if isinstance(info, dict) and 'count' in info and 'total' in info:
                    cnt = info['count']
                    tot = info['total']
                    if cnt == 0:
                        continue
                    # sanity checks
                    if not isinstance(tot, (int, float)) or not isinstance(cnt, (int, float)):
                        raise TypeError(f"Invalid total/count for student {student!r}: {info!r}")
                    if tot < 0:
                        # if totals are negative but counts positive, it's still invalid per spec
                        raise ValueError(f"Negative total encountered for student {student!r}: {tot}")
                    averages[student] = float(tot) / float(cnt)
                else:
                    # Unexpected shape: try to treat info as a single numeric average
                    if isinstance(info, (int, float)):
                        if info < 0:
                            raise ValueError(f"Negative average for student {student!r}: {info}")
                        averages[student] = float(info)
                    else:
                        # cannot interpret
                        raise TypeError(f"Cannot interpret combined data for student {student!r}: {info!r}")
    else:
        raise TypeError("Combined data from student_score_aggregator is not a dict and cannot be interpreted")

    # Filter out students with no scores (shouldn't be present) and sort for deterministic plotting
    if not averages:
        # create and return an empty figure
        import matplotlib.pyplot as plt
        fig, ax = plt.subplots()
        ax.set_xlabel("Student")
        ax.set_ylabel("Average Score")
        ax.set_title("Average Student Scores")
        return fig

    names = sorted(averages.keys())
    values = [averages[n] for n in names]

    # Final check: no negative averages
    for n, v in zip(names, values):
        if v < 0:
            raise ValueError(f"Negative average for student {n!r}: {v}")

    # Plot
    import matplotlib.pyplot as plt
    fig, ax = plt.subplots(figsize=(max(6, 0.6 * len(names)), 4))  # adjust width to fit names
    bars = ax.bar(names, values, color=color)
    ax.set_xlabel("Student")
    ax.set_ylabel("Average Score")
    ax.set_title("Average Student Scores")
    ax.set_ylim(bottom=0)  # scores are non-negative per spec

    # Optional: annotate bars with numeric values
    for bar, val in zip(bars, values):
        height = bar.get_height()
        ax.annotate(f"{val:.2f}",
                    xy=(bar.get_x() + bar.get_width() / 2, height),
                    xytext=(0, 3),
                    textcoords="offset points",
                    ha='center', va='bottom', fontsize=8)

    plt.tight_layout()
    return fig

