import requests
import unicodedata
from typing import Any, Callable, Dict
import github_user_normalizer as gnorm


def get_normalized_github_user(username: str, token: str = None, timeout: float = 10.0) -> Dict[str, Any]:
    """
    Retrieve a GitHub user's public profile from the GitHub API and normalize all string data to ASCII.

    Uses the github_user_normalizer library if it exposes a suitable normalization function; otherwise,
    falls back to a safe Unicode-to-ASCII normalization that strips non-ASCII characters.

    Parameters:
    - username: GitHub username to lookup (str).
    - token: optional GitHub personal access token (str). If provided, it will be used for authenticated requests.
    - timeout: request timeout in seconds (float).

    Returns:
    - A dict mirroring the JSON returned by https://api.github.com/users/{username}, but with all string
      values (and string keys) normalized to ASCII.

    Raises:
    - requests.HTTPError on non-2xx responses from GitHub.
    - requests.RequestException on network-related errors.
    - ValueError on invalid input.
    """
    if not username or not isinstance(username, str):
        raise ValueError("username must be a non-empty string")

    # Determine normalization function from github_user_normalizer (try several common names).
    norm_fn: Callable[[str], str]
    if hasattr(gnorm, "normalize_to_ascii"):
        norm_fn = getattr(gnorm, "normalize_to_ascii")
    elif hasattr(gnorm, "normalize_string"):
        norm_fn = getattr(gnorm, "normalize_string")
    elif hasattr(gnorm, "normalize"):
        norm_fn = getattr(gnorm, "normalize")
    elif hasattr(gnorm, "to_ascii"):
        norm_fn = getattr(gnorm, "to_ascii")
    else:
        # Fallback: decompose Unicode and drop non-ASCII characters
        def _fallback_normalize(s: str) -> str:
            if not isinstance(s, str):
                s = str(s)
            nfkd = unicodedata.normalize("NFKD", s)
            return nfkd.encode("ascii", "ignore").decode("ascii")
        norm_fn = _fallback_normalize

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    resp = requests.get(url, headers=headers, timeout=timeout)
    # Raise for HTTP errors (404, 403, etc.) with an informative message.
    try:
        resp.raise_for_status()
    except requests.HTTPError as e:
        # Attach the response content (if any) to the error message for easier debugging.
        content = resp.text.strip()
        raise requests.HTTPError(f"{e}. Response content: {content}") from e

    data = resp.json()

    def normalize_value(value: Any) -> Any:
        # Recursively normalize strings inside dicts/lists/tuples.
        if isinstance(value, str):
            return norm_fn(value)
        if isinstance(value, bytes):
            try:
                s = value.decode("utf-8")
            except Exception:
                s = value.decode("latin-1", errors="ignore")
            return norm_fn(s)
        if isinstance(value, dict):
            # Normalize keys and values. Note that key collisions could occur if different keys
            # normalize to the same ASCII string; this implementation will let later keys win.
            new_d = {}
            for k, v in value.items():
                new_key = norm_fn(k) if isinstance(k, str) else k
                new_d[new_key] = normalize_value(v)
            return new_d
        if isinstance(value, list):
            return [normalize_value(v) for v in value]
        if isinstance(value, tuple):
            return tuple(normalize_value(v) for v in value)
        # Leave other types (int, bool, None, float) as-is
        return value

    normalized = normalize_value(data)
    return normalized
