def analyze_publication_times(articles, target_timezone):
    """
    Analyze publication times of articles.

    Parameters:
    - articles: iterable of dict-like objects with keys:
        - 'published_time': can be a datetime, an ISO string, or a POSIX timestamp (int/float)
        - 'category': string
    - target_timezone: timezone string (e.g., "Europe/London", "UTC", "America/New_York")

    Returns:
    - dict mapping category -> {
            'count': int,
            'mean_hour': float (0 <= mean_hour < 24)  # circular mean of hours,
            'min_hour': int (0-23),
            'max_hour': int (0-23)
      }

    Notes:
    - Uses publication_time_analyzer (if available) for parsing/conversion.
    - If publication_time_analyzer helpers are not available, falls back to dateutil + pytz.
    - Naive datetimes or timezone-less strings are assumed to be in UTC by default.
    """

    # Validate target timezone (if pytz available)
    tz = None
    if pta is not None:
        # If pta exposes a timezone resolver, use it; otherwise fall back
        tz = getattr(pta, "get_timezone", None)
        if callable(tz):
            try:
                tz = tz(target_timezone)
            except Exception:
                tz = None
        else:
            tz = None

    if tz is None:
        # Try pytz
        if pytz is None:
            raise RuntimeError(
                "pytz is required as a fallback to resolve timezones when publication_time_analyzer"
                " doesn't provide timezone helpers."
            )
        try:
            tz = pytz.timezone(target_timezone)
        except Exception as exc:
            raise ValueError(f"Unknown timezone '{target_timezone}': {exc}")

    def to_datetime_in_tz(published_time):
        """
        Convert various published_time formats to a timezone-aware datetime in tz.
        Accepts:
        - datetime (naive or aware)
        - ISO string (with or without tz info)
        - POSIX timestamp (int/float)
        """
        # If publication_time_analyzer has a helper to parse/convert, try to use it
        if pta is not None:
            # Try a few commonly named helpers if they exist
            for helper_name in ("parse_datetime", "parse_published_time", "to_timezone", "convert_to_timezone", "convert_time"):
                helper = getattr(pta, helper_name, None)
                if callable(helper):
                    try:
                        # Some helpers might accept (value, tz) and return tz-aware datetime
                        dt = helper(published_time, target_timezone)
                        if isinstance(dt, datetime):
                            return dt.astimezone(tz)
                    except Exception:
                        # ignore and try next helper
                        pass

        # Fallback handling
        # If it's already a datetime
        if isinstance(published_time, datetime):
            dt = published_time
        elif isinstance(published_time, (int, float)):
            # treat as POSIX timestamp (seconds)
            dt = datetime.utcfromtimestamp(published_time).replace(tzinfo=pytz.UTC)
            return dt.astimezone(tz)
        elif isinstance(published_time, str):
            if dateutil_parser is None:
                raise RuntimeError("dateutil is required to parse string datetimes when publication_time_analyzer helpers are unavailable.")
            dt = dateutil_parser.parse(published_time)
        else:
            raise TypeError(f"Unsupported published_time type: {type(published_time)}")

        # If naive, assume UTC by default
        if dt.tzinfo is None:
            if pytz is None:
                raise RuntimeError("pytz is required to localize naive datetimes.")
            dt = pytz.UTC.localize(dt)

        # Convert to target tz
        return dt.astimezone(tz)

    # Group hours per category
    hours_by_category = defaultdict(list)
    for art in articles:
        # Ensure article has required fields
        if not isinstance(art, dict):
            # try attribute access
            try:
                published_time = getattr(art, "published_time")
                category = getattr(art, "category")
            except Exception:
                raise TypeError("Each article must be a dict or have 'published_time' and 'category' attributes.")
        else:
            if "published_time" not in art or "category" not in art:
                raise KeyError("Each article dict must contain 'published_time' and 'category' keys.")
            published_time = art["published_time"]
            category = art["category"]

        # Skip articles with missing/None published_time or category
        if published_time is None or category is None:
            continue

        # Convert to tz-aware datetime in target tz
        try:
            dt_in_tz = to_datetime_in_tz(published_time)
        except Exception as exc:
            # Skip or raise; here we'll skip invalid items but you can change to raise
            # raise
            continue

        hour = dt_in_tz.hour  # 0..23
        hours_by_category[category].append(hour)

    # Compute stats per category
    results = {}
    for category, hours in hours_by_category.items():
        if not hours:
            continue
        count = len(hours)
        # min and max as numeric hours
        min_hour = min(hours)
        max_hour = max(hours)

        # Circular mean of hours (treat 0..24 as circle)
        angles = [ (h / 24.0) * (2.0 * math.pi) for h in hours ]
        sin_sum = sum(math.sin(a) for a in angles) / count
        cos_sum = sum(math.cos(a) for a in angles) / count
        mean_angle = math.atan2(sin_sum, cos_sum)
        if mean_angle < 0:
            mean_angle += 2.0 * math.pi
        mean_hour = (mean_angle / (2.0 * math.pi)) * 24.0

        results[category] = {
            "count": count,
            "mean_hour": mean_hour,   # float in [0,24)
            "min_hour": min_hour,     # int 0..23
            "max_hour": max_hour,     # int 0..23
        }

    return results
