def count_xyz_values(d):
    """
    Count occurrences of values for keys "x", "y" and "z" in a list of dictionaries `d`.
    Uses the dict_key_counter library if available; otherwise falls back to a pure-Python implementation.

    Args:
        d (list): List of dictionaries to scan.

    Returns:
        dict: Mapping of key -> {value: count, ...}, e.g.
              { "x": {1: 2, 3: 1}, "y": {"a": 1}, "z": {} }
    """
    keys = ("x", "y", "z")

    # Try to use dict_key_counter if present (supporting a few plausible APIs).
    try:
        import dict_key_counter as dkc
        # If the library exposes a function named count_values(d, key) that returns mapping
        if hasattr(dkc, "count_values"):
            return {k: dict(dkc.count_values(d, k)) for k in keys}
        # If the library exposes a class DictKeyCounter(d) with useful methods/attributes
        if hasattr(dkc, "DictKeyCounter"):
            try:
                counter = dkc.DictKeyCounter(d)
                # try method counts_for(key)
                if hasattr(counter, "counts_for"):
                    return {k: dict(counter.counts_for(k)) for k in keys}
                # try attribute counts mapping
                if hasattr(counter, "counts"):
                    counts = getattr(counter, "counts")
                    return {k: dict(counts.get(k, {})) for k in keys}
            except Exception:
                # fall through to fallback if usage fails
                pass
        # If the library exposes some other plausible function name
        if hasattr(dkc, "count_keys"):
            return {k: dict(dkc.count_keys(d, k)) for k in keys}
    except Exception:
        # If import fails or any usage error occurs, use fallback implementation below
        pass

    # Pure-Python fallback using collections.Counter
    from collections import Counter
    counters = {k: Counter() for k in keys}
    for item in d:
        if not isinstance(item, dict):
            continue
        for k in keys:
            if k in item:
                counters[k][item[k]] += 1
    return {k: dict(counters[k]) for k in keys}

