def generate_and_plot_sales_forecast(start_date,
                                     periods,
                                     freq='D',
                                     model_kwargs=None,
                                     figsize=(10, 5),
                                     title="Sales forecast"):
    """
    Generate and plot a sales forecast starting from `start_date` for `periods` periods
    with frequency `freq`, using the `sales_forecaster` library.

    The function will:
    - Try to call common forecast APIs found in different versions of `sales_forecaster`.
    - Return a pandas.DataFrame with the forecast values (and optionally lower/upper intervals if provided).
    - Plot the point forecast and (if available) prediction intervals.

    Parameters:
    - start_date: str or datetime-like, start date of the forecast (inclusive).
    - periods: int, number of periods to forecast.
    - freq: string, pandas offset alias for frequency (e.g. 'D', 'W', 'M').
    - model_kwargs: dict or None, optional kwargs passed to the library's forecast call.
    - figsize: tuple, size of the matplotlib figure.
    - title: str, title used for the plot.

    Returns:
    - forecast_df: pandas.DataFrame with a DateTimeIndex and at least a 'forecast' column.
      If the underlying library returns intervals, column names like 'lower' and 'upper' are preserved.
    """
    import importlib
    import pandas as pd
    import matplotlib.pyplot as plt

    if model_kwargs is None:
        model_kwargs = {}

    # Try to import the sales_forecaster library
    try:
        sf = importlib.import_module("sales_forecaster")
    except Exception as e:
        raise ImportError(
            "The 'sales_forecaster' library could not be imported. "
            "Install it (for example `pip install sales_forecaster`) or make sure it is on PYTHONPATH."
        ) from e

    # Normalize start_date and build index for the forecast horizon
    start_ts = pd.to_datetime(start_date)
    idx = pd.date_range(start=start_ts, periods=periods, freq=freq)

    forecast_df = None

    # Try a few common API patterns that a forecaster library might expose.
    # 1) A top-level function like generate_forecast/create_forecast
    for fn_name in ("generate_forecast", "create_forecast", "forecast"):
        if hasattr(sf, fn_name) and callable(getattr(sf, fn_name)):
            fn = getattr(sf, fn_name)
            # Try a few argument signatures
            try:
                res = fn(start_date=start_ts, periods=periods, freq=freq, **model_kwargs)
            except TypeError:
                try:
                    res = fn(start=start_ts, periods=periods, freq=freq, **model_kwargs)
                except TypeError:
                    try:
                        # positional
                        res = fn(start_ts, periods, freq, **model_kwargs)
                    except TypeError:
                        res = None
            if res is not None:
                forecast_res = res
                break
    else:
        # 2) A Forecaster / SalesForecaster class with a forecast/predict method
        forecaster_obj = None
        for cls_name in ("SalesForecaster", "Forecaster", "Model"):
            if hasattr(sf, cls_name):
                try:
                    forecaster_obj = getattr(sf, cls_name)()
                    break
                except Exception:
                    # maybe constructor requires args; try without creating instance
                    try:
                        forecaster_obj = getattr(sf, cls_name)
                        break
                    except Exception:
                        forecaster_obj = None
        forecast_res = None
        if forecaster_obj is not None:
            # Try common instance methods
            for method_name in ("forecast", "predict", "generate_forecast", "create_forecast"):
                if hasattr(forecaster_obj, method_name):
                    method = getattr(forecaster_obj, method_name)
                    try:
                        forecast_res = method(start_date=start_ts, periods=periods, freq=freq, **model_kwargs)
                        break
                    except TypeError:
                        try:
                            forecast_res = method(start=start_ts, periods=periods, freq=freq, **model_kwargs)
                            break
                        except TypeError:
                            try:
                                forecast_res = method(start_ts, periods, freq, **model_kwargs)
                                break
                            except Exception:
                                forecast_res = None
                    except Exception:
                        forecast_res = None

    if forecast_res is None:
        raise RuntimeError(
            "Unable to call a forecast function on the 'sales_forecaster' package. "
            "The wrapper tried common function/class names (generate_forecast, create_forecast, forecast, "
            "SalesForecaster, Forecaster) and multiple argument patterns. "
            "Please adapt model_kwargs or the library API."
        )

    # Normalize the returned result into a DataFrame with index `idx`
    if isinstance(forecast_res, pd.DataFrame):
        forecast_df = forecast_res.copy()
        # If index does not match, reindex or set index
        if not isinstance(forecast_df.index, pd.DatetimeIndex) or len(forecast_df) != periods:
            try:
                forecast_df.index = idx
            except Exception:
                forecast_df = forecast_df.reset_index(drop=True)
                forecast_df.index = idx
    elif isinstance(forecast_res, pd.Series):
        forecast_df = forecast_res.to_frame(name="forecast")
        if not isinstance(forecast_df.index, pd.DatetimeIndex) or len(forecast_df) != periods:
            forecast_df.index = idx
    elif isinstance(forecast_res, (list, tuple)):
        # Could be simple list of values or (values, lower, upper)
        try:
            arr = pd.DataFrame(forecast_res).T  # try to orient
            if arr.shape[0] == periods:
                arr.index = idx
                # name columns sensibly
                if arr.shape[1] == 1:
                    arr.columns = ["forecast"]
                elif arr.shape[1] == 2:
                    arr.columns = ["forecast", "lower"]
                elif arr.shape[1] >= 3:
                    arr.columns = ["forecast", "lower", "upper"] + [f"extra_{i}" for i in range(arr.shape[1] - 3)]
                forecast_df = arr
            else:
                # treat as single vector
                ser = pd.Series(forecast_res)
                ser.index = idx
                forecast_df = ser.to_frame(name="forecast")
        except Exception:
            # fallback: convert to pandas Series
            ser = pd.Series(list(forecast_res), index=idx)
            forecast_df = ser.to_frame(name="forecast")
    else:
        # Could be numpy array-like
        try:
            import numpy as np
            if hasattr(forecast_res, "__array__") or isinstance(forecast_res, (list, tuple)):
                arr = pd.Series(forecast_res, index=idx)
                forecast_df = arr.to_frame(name="forecast")
            else:
                raise TypeError("Unrecognized forecast return type: " + str(type(forecast_res)))
        except Exception as e:
            raise TypeError("Unrecognized forecast return type: " + str(type(forecast_res))) from e

    # Ensure a 'forecast' column exists
    if "forecast" not in forecast_df.columns:
        # try to pick a sensible first numeric column
        numeric_cols = [c for c in forecast_df.columns if pd.api.types.is_numeric_dtype(forecast_df[c])]
        if numeric_cols:
            forecast_df = forecast_df.rename(columns={numeric_cols[0]: "forecast"})
        else:
            # create forecast column from first column
            first_col = forecast_df.columns[0]
            forecast_df = forecast_df.rename(columns={first_col: "forecast"})

    # Plotting
    plt.figure(figsize=figsize)
    ax = plt.gca()
    ax.plot(forecast_df.index, forecast_df["forecast"], label="Forecast", color="tab:blue")
    # If lower/upper exist, plot as band
    lower_col = None
    upper_col = None
    for candidate in ("lower", "lower_bound", "yhat_lower", "min"):
        if candidate in forecast_df.columns:
            lower_col = candidate
            break
    for candidate in ("upper", "upper_bound", "yhat_upper", "max"):
        if candidate in forecast_df.columns:
            upper_col = candidate
            break
    if lower_col is not None and upper_col is not None:
        ax.fill_between(forecast_df.index,
                        forecast_df[lower_col],
                        forecast_df[upper_col],
                        color="tab:blue", alpha=0.2, label="Prediction interval")
    elif "std" in forecast_df.columns:
        # if std provided, plot +/- 1 std
        ax.fill_between(forecast_df.index,
                        forecast_df["forecast"] - forecast_df["std"],
                        forecast_df["forecast"] + forecast_df["std"],
                        color="tab:blue", alpha=0.2, label="±1 std")
    ax.set_title(title)
    ax.set_xlabel("Date")
    ax.set_ylabel("Sales")
    ax.legend()
    plt.tight_layout()
    plt.show()

    return forecast_df

