def extract_and_visualize_json_numbers(json_obj, path, plot='line',
                                       title=None, xlabel=None, ylabel=None,
                                       show=True, return_fig=False):
    """
    Extract numeric values from a JSON-like structure following a path and visualize them.

    Parameters:
    - json_obj: Python dict/list representing JSON data.
    - path: list of keys/indices or dot-separated string. Supports '*' as wildcard to
            iterate all children of a list/dict. Examples:
            - "a.b.c"
            - ["a", "*", "value"]
            - "items.*.0"   (select 0th item inside every element of items)
            - "" or None to collect numeric leaves from the whole structure.
    - plot: one of {'line', 'scatter', 'hist', 'bar'} (default 'line').
    - title, xlabel, ylabel: optional labels for the plot.
    - show: whether to display the plot (default True).
    - return_fig: if True return the plotting object (matplotlib.Figure or jsondata_viz result)
                 along with values.

    Returns:
    - dict with keys:
        - 'values': list of extracted numeric values
        - 'viz': the plotting result/figure (only present if return_fig=True)
    Notes:
    - Requires jsondata_viz if you want to use that library's plotting API; if not installed,
      matplotlib will be used automatically.
    """

    import numbers

    # Normalize path into list of parts
    if path is None:
        path_parts = []
    elif isinstance(path, (list, tuple)):
        path_parts = list(path)
    elif isinstance(path, str):
        path = path.strip()
        path_parts = [] if path == '' else path.split('.')
    else:
        # single atomic key (int or str)
        path_parts = [path]

    # Convert numeric-looking strings to int when appropriate (except '*')
    def _normalize_part(p):
        if isinstance(p, str) and p != '*' and p.isdigit():
            return int(p)
        return p

    path_parts = [_normalize_part(p) for p in path_parts]

    # Recursive traversal to collect numeric values
    def traverse(obj, parts):
        if not parts:
            # If no more path parts: collect numeric leaves from obj
            if isinstance(obj, numbers.Number) and not isinstance(obj, bool):
                yield obj
            elif isinstance(obj, dict):
                for v in obj.values():
                    yield from traverse(v, [])
            elif isinstance(obj, (list, tuple)):
                for item in obj:
                    yield from traverse(item, [])
            # else: non-numeric leaf ignored
            return

        part = parts[0]
        rest = parts[1:]

        # Wildcard: iterate children if dict or list
        if part == '*':
            if isinstance(obj, dict):
                for v in obj.values():
                    yield from traverse(v, rest)
            elif isinstance(obj, (list, tuple)):
                for item in obj:
                    yield from traverse(item, rest)
            # else nothing to iterate
            return

        # If part is an integer index
        if isinstance(part, int):
            if isinstance(obj, (list, tuple)):
                idx = part
                if -len(obj) <= idx < len(obj):
                    yield from traverse(obj[idx], rest)
            else:
                # Trying to index a non-list: nothing
                return
            return

        # If part is a string (dict key)
        if isinstance(part, str):
            if isinstance(obj, dict):
                if part in obj:
                    yield from traverse(obj[part], rest)
            elif isinstance(obj, (list, tuple)):
                # If list and part is numeric string already handled; if dict-like strings inside list,
                # try mapping each element if it's a dict and has key
                for item in obj:
                    if isinstance(item, dict) and part in item:
                        yield from traverse(item[part], rest)
            # else: nothing
            return

        # Fallback: unsupported part type -> nothing
        return

    # Collect values
    values = list(traverse(json_obj, path_parts))

    # Filter out NaN/inf and non-finite numbers
    import math
    filtered_values = []
    for v in values:
        try:
            if isinstance(v, numbers.Number) and not isinstance(v, bool) and math.isfinite(float(v)):
                filtered_values.append(float(v))
        except Exception:
            continue

    # Visualization: try to use jsondata_viz, else matplotlib
    viz_result = None
    try:
        import jsondata_viz
        # Try common interfaces on jsondata_viz
        if hasattr(jsondata_viz, 'plot'):
            # jsondata_viz.plot(values, kind=..., title=..., xlabel=..., ylabel=..., show=...)
            try:
                viz_result = jsondata_viz.plot(filtered_values, kind=plot,
                                               title=title, xlabel=xlabel, ylabel=ylabel,
                                               show=show)
            except TypeError:
                # If signature is different, try alternative kw names
                viz_result = jsondata_viz.plot(filtered_values, plot_type=plot,
                                               title=title, x_label=xlabel, y_label=ylabel)
                if show and hasattr(viz_result, 'show'):
                    try:
                        viz_result.show()
                    except Exception:
                        pass
        elif hasattr(jsondata_viz, 'visualize'):
            # jsondata_viz.visualize(data, type=...)
            try:
                viz_result = jsondata_viz.visualize(filtered_values, type=plot,
                                                    title=title, xlabel=xlabel, ylabel=ylabel)
                if show and hasattr(viz_result, 'show'):
                    try:
                        viz_result.show()
                    except Exception:
                        pass
            except TypeError:
                viz_result = jsondata_viz.visualize(filtered_values, kind=plot)
                if show and hasattr(viz_result, 'show'):
                    try:
                        viz_result.show()
                    except Exception:
                        pass
        else:
            # jsondata_viz present but no known plotting helpers; fall back to matplotlib
            raise ImportError("jsondata_viz does not expose a recognized plotting function.")
    except Exception:
        # Fallback plotting with matplotlib
        try:
            import matplotlib.pyplot as plt
            fig, ax = plt.subplots()
            if plot == 'line':
                ax.plot(filtered_values, marker='o')
                if xlabel is None:
                    xlabel = 'index'
                if ylabel is None:
                    ylabel = 'value'
            elif plot == 'scatter':
                ax.scatter(list(range(len(filtered_values))), filtered_values)
                if xlabel is None:
                    xlabel = 'index'
                if ylabel is None:
                    ylabel = 'value'
            elif plot == 'hist':
                ax.hist(filtered_values, bins='auto')
                if xlabel is None:
                    xlabel = 'value'
                if ylabel is None:
                    ylabel = 'count'
            elif plot == 'bar':
                ax.bar(list(range(len(filtered_values))), filtered_values)
                if xlabel is None:
                    xlabel = 'index'
                if ylabel is None:
                    ylabel = 'value'
            else:
                # unknown plot kind: default to line
                ax.plot(filtered_values, marker='o')
                if xlabel is None:
                    xlabel = 'index'
                if ylabel is None:
                    ylabel = 'value'

            if title:
                ax.set_title(title)
            if xlabel:
                ax.set_xlabel(xlabel)
            if ylabel:
                ax.set_ylabel(ylabel)

            if show:
                plt.show()

            viz_result = fig
        except Exception as e:
            # If plotting totally fails, set viz_result to the exception for debugging.
            viz_result = e

    result = {'values': filtered_values}
    if return_fig:
        result['viz'] = viz_result
    return result
