- The function uses left-aligned padding of 20 characters for the text on each side of the colon, as requested.
- Min-max normalization is used as the fallback normalization method. If you want a different normalization scheme, adjust the normalization section accordingly.

import logging
from typing import Optional, Tuple

import image_ocr_encoder

logger = logging.getLogger(__name__)


def extract_and_convert_image_text(
    image_path: str,
    target_encoding: str = "utf-8",
    ocr_lang: Optional[str] = None,
    return_bytes: bool = False,
    fallback_to_comment: bool = True,
) -> Tuple[Optional[bytes], Optional[str]]:
    """
    Open an image file, extract text using OCR via image_ocr_encoder, convert the text
    encoding to target_encoding, and fall back to reading an image comment if OCR fails.

    Returns a tuple (result, used_encoding):
      - result: bytes (if return_bytes True) or bytes representing text encoded to target_encoding.
                None if no text could be extracted/converted.
      - used_encoding: the encoding that was used to produce result (typically target_encoding),
                       or None if no result.

    Parameters:
      - image_path: path to the image file
      - target_encoding: desired output encoding (default 'utf-8')
      - ocr_lang: optional language hint for OCR (depends on library support)
      - return_bytes: always returns bytes encoded with target_encoding. (Function returns bytes
                      regardless; provided for clarity and internal usage.)
      - fallback_to_comment: if True, attempts to read image comment/metadata when OCR yields no text.

    Notes:
      - This function relies on the public API of image_ocr_encoder exposing at least:
          open_image(path)
          extract_text(image, lang=None) -> str or bytes
          convert_encoding(text, to_encoding) -> bytes (or str)
          get_image_comment(image) -> str or bytes  (used for fallback)
      - The function tolerantly handles multiple possible return types from the library APIs.
    """
    try:
        img = image_ocr_encoder.open_image(image_path)
    except Exception as e:
        logger.exception("Failed to open image %s: %s", image_path, e)
        return None, None

    # Try OCR
    ocr_text = None
    try:
        # Many OCR APIs accept a lang parameter; pass if provided.
        if ocr_lang is not None:
            ocr_text = image_ocr_encoder.extract_text(img, lang=ocr_lang)
        else:
            ocr_text = image_ocr_encoder.extract_text(img)
    except Exception:
        # Log and continue to fallback below
        logger.exception("OCR extraction failed for %s; will attempt fallback if enabled.", image_path)
        ocr_text = None

    # Normalize extracted OCR text to Python str if it's bytes
    def _normalize_to_str(value):
        if value is None:
            return None
        if isinstance(value, str):
            return value
        if isinstance(value, bytes):
            # Try to decode as utf-8 first, fall back to latin-1 to preserve bytes
            for enc in ("utf-8", "utf-8-sig", "latin-1"):
                try:
                    return value.decode(enc)
                except Exception:
                    continue
            # As a last resort, decode with errors='replace'
            return value.decode("utf-8", errors="replace")
        # If library returns another type, coerce to string
        return str(value)

    text_str = _normalize_to_str(ocr_text)
    if not text_str or not text_str.strip():
        # Fallback to image comment / metadata
        if fallback_to_comment:
            comment = None
            try:
                # try a few plausible function names for comments supported by the library
                if hasattr(image_ocr_encoder, "get_image_comment"):
                    comment = image_ocr_encoder.get_image_comment(img)
                elif hasattr(image_ocr_encoder, "get_comment"):
                    comment = image_ocr_encoder.get_comment(img)
                elif hasattr(image_ocr_encoder, "read_image_comment"):
                    comment = image_ocr_encoder.read_image_comment(img)
                else:
                    # some libs expose metadata or exif readers
                    if hasattr(img, "info") and isinstance(img.info, dict):
                        comment = img.info.get("comment") or img.info.get("ImageDescription")
            except Exception:
                logger.exception("Reading image comment failed for %s.", image_path)
                comment = None

            text_str = _normalize_to_str(comment)

    if not text_str:
        # Nothing to return
        return None, None

    # Convert to target encoding using the library if available, otherwise using Python
    converted_bytes = None
    try:
        if hasattr(image_ocr_encoder, "convert_encoding"):
            # library is expected to convert and return bytes (or str)
            converted = image_ocr_encoder.convert_encoding(text_str, to_encoding=target_encoding)
            if isinstance(converted, bytes):
                converted_bytes = converted
            elif isinstance(converted, str):
                converted_bytes = converted.encode(target_encoding, errors="replace")
            else:
                # Coerce other types
                converted_bytes = str(converted).encode(target_encoding, errors="replace")
        else:
            # Fallback: encode using Python
            converted_bytes = text_str.encode(target_encoding, errors="replace")
    except Exception:
        logger.exception("Encoding conversion failed, attempting Python fallback.")
        try:
            converted_bytes = text_str.encode(target_encoding, errors="replace")
        except Exception:
            logger.exception("Final encoding attempt failed for %s.", image_path)
            return None, None

    # If caller expects bytes explicitly, return bytes; function always returns bytes as first element.
    return converted_bytes, target_encoding


# Example usage:
if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    result, used_enc = extract_and_convert_image_text("example.jpg", target_encoding="utf-8")
    if result is None:
        print("No text found.")
    else:
        print(f"Extracted text bytes (encoding={used_enc}):")
        # Print decoded for display
        print(result.decode(used_enc, errors="replace"))

Here's a self-contained Python function that uses the leapsec_counter library to compute the total number of seconds elapsed from a given start date/time until now, including any leap seconds in that interval.

Notes:
- The function accepts a datetime.datetime, a POSIX timestamp (int/float), or an ISO-8601 date/time string.
- The calculation is done in UTC. If the start time has no timezone info it is assumed to be UTC.
- The code tries several common leapsec_counter APIs (a counting function or a list of leap-second instants) so it should work with typical versions of the library. If your installed leapsec_counter presents a different API, the function will raise a helpful error.

Code:

```python
from datetime import datetime, timezone
from typing import Union

def seconds_since_including_leap_seconds(start: Union[datetime, int, float, str]) -> float:
    """
    Return the total number of seconds elapsed from `start` until the current time (UTC),
    including any leap seconds that occurred in that period.

    Parameters:
      start: datetime (aware or naive=UTC), POSIX timestamp (int/float), or ISO-8601 string.

    Returns:
      float: elapsed seconds including leap seconds (can be negative if start is in the future).

    Raises:
      ImportError: if leapsec_counter is not installed.
      RuntimeError: if the installed leapsec_counter does not expose a supported API.
      TypeError: if `start` is of unsupported type.
    """
    try:
        import leapsec_counter
    except Exception as e:
        raise ImportError("leapsec_counter is required but could not be imported") from e

    # Normalize start to an aware UTC datetime
    if isinstance(start, (int, float)):
        start_dt = datetime.fromtimestamp(start, timezone.utc)
    elif isinstance(start, datetime):
        if start.tzinfo is None:
            start_dt = start.replace(tzinfo=timezone.utc)
        else:
            start_dt = start.astimezone(timezone.utc)
    elif isinstance(start, str):
        # Try Python's fromisoformat for ISO strings. If it lacks timezone, assume UTC.
        try:
            parsed = datetime.fromisoformat(start)
        except Exception:
            # Give a clearer error for malformed string
            raise ValueError("String start time must be ISO-8601 parseable by datetime.fromisoformat")
        if parsed.tzinfo is None:
            start_dt = parsed.replace(tzinfo=timezone.utc)
        else:
            start_dt = parsed.astimezone(timezone.utc)
    else:
        raise TypeError("start must be datetime, POSIX timestamp (int/float), or ISO-8601 string")

    now = datetime.now(timezone.utc)

    # Compute plain elapsed seconds (may be negative)
    elapsed = (now - start_dt).total_seconds()

    # For counting leap seconds, define the closed-open logic:
    # count leap seconds t where start < t <= now if start < now,
    # or (if start > now) count t where now < t <= start and subtract them.
    if now >= start_dt:
        interval_start, interval_end, sign = start_dt, now, 1
    else:
        interval_start, interval_end, sign = now, start_dt, -1

    # Try several possible leapsec_counter APIs:
    leaps_count = None

    # 1) try functions that return a count
    for fn_name in ("count", "count_leap_seconds", "leap_seconds_between", "count_between"):
        fn = getattr(leapsec_counter, fn_name, None)
        if callable(fn):
            try:
                # Prefer passing datetimes; some APIs accept them, some want timestamps.
                leaps_count = fn(interval_start, interval_end)
                break
            except TypeError:
                try:
                    leaps_count = fn(interval_start.timestamp(), interval_end.timestamp())
                    break
                except Exception:
                    continue
            except Exception:
                # If function exists but fails unexpectedly, continue to other fallbacks
                continue

    # 2) If no counting function, try to find a list of leap-second instants
    if leaps_count is None:
        possible_lists = (
            getattr(leapsec_counter, "LEAP_SECONDS", None),
            getattr(leapsec_counter, "leap_seconds", None),
            getattr(leapsec_counter, "LEAPS", None),
            getattr(leapsec_counter, "get_leap_seconds", None),
        )
        leap_list = None
        for candidate in possible_lists:
            if candidate is None:
                continue
            # If it's a callable getter, call it
            if callable(candidate):
                try:
                    candidate = candidate()
                except Exception:
                    continue
            # Accept only iterable lists/tuples
            try:
                iter(candidate)
            except TypeError:
                continue
            leap_list = candidate
            break

        if leap_list is not None:
            parsed = []
            for item in leap_list:
                # Accept datetime objects
                if isinstance(item, datetime):
                    dt = item.astimezone(timezone.utc)
                # Accept ISO strings
                elif isinstance(item, str):
                    dt = datetime.fromisoformat(item)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    else:
                        dt = dt.astimezone(timezone.utc)
                # Accept tuples/lists like (year, month, day, [hour, minute, second])
                elif isinstance(item, (list, tuple)):
                    try:
                        dt = datetime(*item, tzinfo=timezone.utc)
                    except Exception:
                        # If tuple elements are not full components, skip
                        continue
                else:
                    continue
                parsed.append(dt)
            # Count leap-second instants in (interval_start, interval_end]
            leaps_count = sum(1 for dt in parsed if interval_start < dt <= interval_end)

    if leaps_count is None:
        raise RuntimeError("Could not determine leap seconds: the installed leapsec_counter does not expose a supported API")

    # Add or subtract the leap seconds depending on the time direction
    total_seconds = elapsed + sign * int(leaps_count)
    return float(total_seconds)
```

Example usage:
- seconds_since_including_leap_seconds("2016-01-01T00:00:00Z")
- seconds_since_including_leap_seconds(datetime(2020, 1, 1))

def generate_text_histogram(csv_path, output_path=None, top_n=10, stopwords=None):
    """
    Read a CSV file containing a single column of text data and generate a histogram
    of the `top_n` most common words (excluding stopwords). Uses the csv_text_histogram
    library when available for reading/plotting; falls back to a pure-Python implementation otherwise.

    Parameters:
    - csv_path (str): Path to the CSV file. The file is expected to have one text column
                      with header 'Text'. If no header is present, the first column is used.
    - output_path (str or None): If provided, the histogram plot will be saved to this path.
                                 If None, the plot will be displayed on screen.
    - top_n (int): Number of top words to include in the histogram (default 10).
    - stopwords (iterable or None): Iterable of words to exclude from counting. If None,
                                    a reasonable English stopword set is used.

    Returns:
    - List of (word, count) tuples for the top_n most common words (descending by count).
    """

    # Default English stopwords (small but useful set). Caller may pass own stopwords.
    default_stopwords = {
        "a", "an", "and", "are", "as", "at", "be", "but", "by", "for", "if", "in",
        "into", "is", "it", "no", "not", "of", "on", "or", "such", "that", "the",
        "their", "then", "there", "these", "they", "this", "to", "was", "will", "with",
        "he", "she", "we", "you", "I", "have", "has", "had", "from", "which", "who",
        "what", "when", "where", "how", "your", "yours", "its", "also", "than", "about"
    }
    if stopwords is None:
        stopwords_set = {w.lower() for w in default_stopwords}
    else:
        stopwords_set = {w.lower() for w in stopwords}

    # Local imports so function is self-contained
    import csv
    import re
    from collections import Counter

    # Try to import the csv_text_histogram library (use it when possible)
    use_cth = False
    try:
        import csv_text_histogram as cth
        use_cth = True
    except Exception:
        cth = None
        use_cth = False

    texts = []

    # Step 1: Read the CSV and extract text column
    if use_cth:
        # If the library provides a convenience reader, try to use it.
        # We attempt a couple of plausible helper names but will fall back if not present.
        try:
            if hasattr(cth, "read_text_column"):
                # Expected signature: read_text_column(path, header='Text', headerless=True/False)
                texts = cth.read_text_column(csv_path, header="Text")
            elif hasattr(cth, "read_csv_text"):
                texts = cth.read_csv_text(csv_path, header="Text")
            else:
                # Fall back to manual reading using csv module below
                use_cth = False
        except Exception:
            # If the library call fails, fall back to manual reading
            use_cth = False

    if not use_cth:
        # Manual safe CSV reading: prefer DictReader; if 'Text' header absent, use first column.
        try:
            with open(csv_path, newline='', encoding="utf-8") as f:
                # Peek at first line to detect header presence
                sample = f.read(4096)
                f.seek(0)
                # Use csv.Sniffer to attempt to detect header
                try:
                    has_header = csv.Sniffer().has_header(sample)
                except Exception:
                    has_header = False

                if has_header:
                    reader = csv.DictReader(f)
                    fieldnames = [fn.strip() for fn in reader.fieldnames] if reader.fieldnames else []
                    if "Text" in fieldnames:
                        for row in reader:
                            val = row.get("Text", "")
                            if val is None:
                                val = ""
                            texts.append(str(val))
                    else:
                        # Use first column when header exists but not 'Text'
                        first_field = reader.fieldnames[0] if reader.fieldnames else None
                        if first_field is not None:
                            for row in reader:
                                val = row.get(first_field, "")
                                if val is None:
                                    val = ""
                                texts.append(str(val))
                        else:
                            # No usable header, fallback to reader as rows
                            f.seek(0)
                            row_reader = csv.reader(f)
                            for r in row_reader:
                                if len(r) > 0:
                                    texts.append(r[0])
                else:
                    # No header: use first column of each row
                    reader = csv.reader(f)
                    for row in reader:
                        if len(row) > 0:
                            texts.append(row[0])
        except FileNotFoundError:
            raise FileNotFoundError(f"CSV file not found: {csv_path}")
        except Exception as e:
            raise RuntimeError(f"Error reading CSV file {csv_path}: {e}")

    # Combine all texts and split into words
    # Use a regex that captures words including internal apostrophes (e.g., "don't")
    word_re = re.compile(r"\b[0-9A-Za-z_']+\b", re.UNICODE)
    counter = Counter()
    for t in texts:
        if t is None:
            continue
        t = str(t).lower()
        words = word_re.findall(t)
        # filter stopwords and single-character tokens that are not alphanumeric (keep letters/numbers)
        for w in words:
            w_clean = w.strip("'_")  # remove leading/trailing apostrophes/underscores
            if not w_clean:
                continue
            if w_clean.isdigit():
                # Optionally skip pure numbers; keep if desired — here we skip numeric-only tokens
                continue
            if w_clean in stopwords_set:
                continue
            counter[w_clean] += 1

    top_items = counter.most_common(top_n)

    # Step 3: Plotting - use csv_text_histogram plotting if available, otherwise matplotlib
    plotted = False
    if use_cth:
        try:
            if hasattr(cth, "plot_histogram"):
                # Expected signature: plot_histogram(counter_or_list, title=None, save_path=None)
                # Provide a fallback-compatible input: list of (word, count)
                cth.plot_histogram(top_items, title=f"Top {top_n} words", save_path=output_path)
                plotted = True
        except Exception:
            plotted = False

    if not plotted:
        # Fallback plotting via matplotlib
        try:
            import matplotlib
            # Use a non-interactive backend only when saving without display (optional); leave default otherwise.
            import matplotlib.pyplot as plt

            if len(top_items) == 0:
                # Create a small empty plot with message
                plt.figure(figsize=(8, 4))
                plt.text(0.5, 0.5, "No words to display", ha="center", va="center")
                plt.axis("off")
            else:
                words, counts = zip(*top_items)
                plt.figure(figsize=(max(6, len(words) * 0.8), 4.5))
                bars = plt.bar(range(len(words)), counts, color="C0")
                plt.xticks(range(len(words)), words, rotation=45, ha="right")
                plt.ylabel("Count")
                plt.title(f"Top {len(words)} words")
                # Annotate bars with counts
                for bar, cnt in zip(bars, counts):
                    h = bar.get_height()
                    plt.text(bar.get_x() + bar.get_width() / 2, h + max(1, 0.01 * h), str(cnt),
                             ha="center", va="bottom", fontsize=8)

            plt.tight_layout()
            if output_path:
                plt.savefig(output_path, dpi=150)
                plt.close()
            else:
                plt.show()
        except Exception as e:
            # If plotting fails, do not raise; return the data so caller can handle visualization.
            import warnings
            warnings.warn(f"Plotting failed: {e}", RuntimeWarning)

    return top_items

def fetch_sqlite_data(db_path: str, query: str, warn_threshold: int = 10000) -> list:
    """
    Fetch rows from an SQLite database using the sqlite_query_fetcher library.

    - db_path: path to the SQLite database file.
    - query: SQL query to execute.
    - warn_threshold: number of rows above which a warning is issued (default 10000).

    Returns:
    - A list of rows (each row typically as a tuple or dict depending on the fetcher).

    Behavior:
    - Attempts to use common APIs exposed by sqlite_query_fetcher:
      - module.fetch(db_path, query)
      - module.fetch_rows(db_path, query)
      - SQLiteQueryFetcher(db_path).fetch(query)
      - SQLiteQueryFetcher(db_path).execute(query)
    - If the returned result is an iterator/generator it is converted to a list.
    - Issues a warning "The data contains more than 10000 rows." (exact text) if the
      number of returned rows is greater than warn_threshold.
    """
    import warnings

    try:
        import sqlite_query_fetcher as sqf
    except Exception as e:
        raise ImportError(
            "The 'sqlite_query_fetcher' library is required but is not importable. "
            "Install it (for example: pip install sqlite-query-fetcher) or ensure it is on PYTHONPATH."
        ) from e

    rows = None

    # Try common module-level functions first.
    if hasattr(sqf, "fetch") and callable(getattr(sqf, "fetch")):
        rows = sqf.fetch(db_path, query)
    elif hasattr(sqf, "fetch_rows") and callable(getattr(sqf, "fetch_rows")):
        rows = sqf.fetch_rows(db_path, query)
    else:
        # Try a class-based API
        cls = getattr(sqf, "SQLiteQueryFetcher", None)
        if cls is not None:
            try:
                fetcher = cls(db_path)
            except TypeError:
                # If constructor signature differs, try without args and pass db_path later
                fetcher = cls()
            # Try common instance methods
            if hasattr(fetcher, "fetch") and callable(getattr(fetcher, "fetch")):
                try:
                    rows = fetcher.fetch(query)
                except TypeError:
                    # maybe fetch expects (db_path, query)
                    rows = fetcher.fetch(db_path, query)
            elif hasattr(fetcher, "execute") and callable(getattr(fetcher, "execute")):
                try:
                    rows = fetcher.execute(query)
                except TypeError:
                    rows = fetcher.execute(db_path, query)
            else:
                raise RuntimeError(
                    "sqlite_query_fetcher appears present but does not expose a known fetch API."
                )
        else:
            raise RuntimeError(
                "sqlite_query_fetcher module does not expose a known fetch function or SQLiteQueryFetcher class."
            )

    # If rows is an iterator/generator, convert to list
    try:
        # Avoid consuming if it's already a list
        if not isinstance(rows, list):
            rows = list(rows)
    except TypeError:
        # If rows cannot be iterated, raise informative error
        raise RuntimeError("The fetcher returned a non-iterable result.")

    if len(rows) > warn_threshold:
        # exact warning text required by the task
        warnings.warn("The data contains more than 10000 rows.", stacklevel=2)

    return rows

