def average_time_difference_seconds(timestamps, timezone='UTC'):
    """
    Calculate the average time difference in seconds between each consecutive pair
    of timestamps in the provided list, after converting them to the specified timezone.

    - timestamps: iterable of datetime.datetime objects or timestamp strings (ISO-8601 and many common formats).
                  The function computes differences between consecutive items in the provided order.
    - timezone: a timezone name understood by zoneinfo.ZoneInfo (e.g. "UTC", "America/New_York").

    Returns:
    - float: average difference in seconds between consecutive timestamps (absolute value).
             Returns 0.0 if there are fewer than 2 timestamps.

    Implementation notes:
    - This function will try to use the external avg_time_diff library first (if present).
      If that library doesn't expose a suitable helper, it falls back to a local implementation
      using python's zoneinfo (and dateutil for robust parsing if available).
    """
    from datetime import datetime
    from zoneinfo import ZoneInfo
    import importlib

    # Quick handling for trivial cases
    if timestamps is None:
        raise TypeError("timestamps must be an iterable (list/tuple) of datetimes or strings")
    timestamps = list(timestamps)
    if len(timestamps) < 2:
        return 0.0

    # Try to use avg_time_diff library if available
    try:
        avg_mod = importlib.import_module("avg_time_diff")
        # Common possible APIs: average_time_difference(timestamps, tz) or avg_time_diff(...)
        if hasattr(avg_mod, "average_time_difference"):
            return float(avg_mod.average_time_difference(timestamps, timezone))
        if hasattr(avg_mod, "avg_time_diff"):
            return float(avg_mod.avg_time_diff(timestamps, timezone))
        if hasattr(avg_mod, "average") and callable(getattr(avg_mod, "average")):
            # fallback generic attempt
            return float(avg_mod.average(timestamps, timezone))
        # If the module exists but none of the expected functions were found, fall through to local impl.
    except ModuleNotFoundError:
        # avg_time_diff not installed, do local computation
        pass

    # Local implementation
    # Use dateutil.parser if available for robust parsing, else use datetime.fromisoformat for strings
    try:
        from dateutil import parser as _dateutil_parser  # type: ignore
        _parse = _dateutil_parser.parse
    except Exception:
        _parse = None

    def _parse_timestamp(t):
        if isinstance(t, datetime):
            return t
        if isinstance(t, str):
            if _parse is not None:
                return _parse(t)
            # fallback: try fromisoformat (may raise ValueError)
            return datetime.fromisoformat(t)
        raise TypeError(f"Unsupported timestamp type: {type(t)}. Use str or datetime.datetime.")

    try:
        tzinfo = ZoneInfo(timezone)
    except Exception as e:
        raise ValueError(f"Invalid timezone '{timezone}': {e}") from e

    dt_list = []
    for t in timestamps:
        dt = _parse_timestamp(t)
        # If naive, assume UTC (common default); you may change this assumption as needed.
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=ZoneInfo("UTC"))
        # convert to target timezone
        dt = dt.astimezone(tzinfo)
        dt_list.append(dt)

    # Compute absolute differences in seconds between consecutive elements in the given order
    diffs = []
    for a, b in zip(dt_list, dt_list[1:]):
        secs = (b - a).total_seconds()
        diffs.append(abs(secs))

    if not diffs:
        return 0.0
    return float(sum(diffs) / len(diffs))

