def format_unix_timestamp(timestamp, timezone='UTC', fmt='%Y-%m-%d %H:%M:%S %Z'):
    """
    Convert a Unix timestamp to a formatted date/time string in the given timezone.
    Uses the `timestamp_formatter` library when available; falls back to the
    Python standard library (zoneinfo/backports.zoneinfo) if the library is not
    installed or doesn't expose an expected API.

    Parameters
    - timestamp: int, float, or str representing a Unix timestamp (seconds since epoch).
    - timezone: timezone name string (e.g. "UTC", "America/New_York"). Defaults to "UTC".
    - fmt: strftime-compatible format string. Defaults to '%Y-%m-%d %H:%M:%S %Z'.

    Returns
    - formatted date/time string

    Raises
    - TypeError if timestamp can't be converted to float
    - ValueError if timezone name is invalid (when falling back to stdlib)
    - RuntimeError if neither timestamp_formatter nor zoneinfo/backports.zoneinfo are available
    """
    # Normalize timestamp to float
    try:
        ts = float(timestamp)
    except Exception as e:
        raise TypeError(f"timestamp must be a number or numeric string, got: {timestamp!r}") from e

    # Try to use timestamp_formatter if available
    try:
        import timestamp_formatter as tf  # type: ignore
        # Common possible APIs on the library; try them defensively.
        # 1) tf.format(timestamp, timezone=..., format=...)
        if hasattr(tf, 'format'):
            try:
                return tf.format(ts, timezone=timezone, format=fmt)
            except TypeError:
                # try different param names
                try:
                    return tf.format(ts, tz=timezone, fmt=fmt)
                except Exception:
                    pass

        # 2) tf.format_unix, tf.format_timestamp, tf.format_unix_timestamp
        for fn_name in ('format_unix', 'format_timestamp', 'format_unix_timestamp'):
            if hasattr(tf, fn_name):
                fn = getattr(tf, fn_name)
                # try common parameter names
                for kwargs in ({'timezone': timezone, 'format': fmt},
                               {'tz': timezone, 'fmt': fmt},
                               {'timezone': timezone, 'fmt': fmt},
                               {'tz': timezone, 'format': fmt}):
                    try:
                        return fn(ts, **kwargs)
                    except TypeError:
                        continue
                    except Exception:
                        # If function raises for invalid args, let fallback handle it
                        raise

        # 3) TimestampFormatter class with constructor args
        if hasattr(tf, 'TimestampFormatter'):
            cls = getattr(tf, 'TimestampFormatter')
            try:
                inst = cls(timezone=timezone, format=fmt)
            except TypeError:
                try:
                    inst = cls(tz=timezone, fmt=fmt)
                except TypeError:
                    inst = cls()
            if hasattr(inst, 'format'):
                return inst.format(ts)

        # If we reached here and didn't return, let fallback handle it
    except ModuleNotFoundError:
        # timestamp_formatter not installed; fall back to stdlib
        pass
    except Exception:
        # If timestamp_formatter exists but raised unexpected exceptions, fall back to stdlib
        pass

    # Fallback: use stdlib datetime + zoneinfo (or backports) to format
    try:
        from datetime import datetime, timezone as _timezone
        try:
            from zoneinfo import ZoneInfo  # Python 3.9+
        except Exception:
            try:
                from backports.zoneinfo import ZoneInfo  # type: ignore  # older Pythons if backport installed
            except Exception:
                ZoneInfo = None

        if timezone.upper() == 'UTC':
            tzobj = _timezone.utc
        else:
            if ZoneInfo is None:
                raise RuntimeError(
                    "timestamp_formatter not available and zoneinfo/backports.zoneinfo not installed; "
                    "cannot resolve non-UTC timezones"
                )
            try:
                tzobj = ZoneInfo(timezone)
            except Exception as e:
                raise ValueError(f"Invalid timezone name: {timezone!r}") from e

        dt = datetime.fromtimestamp(ts, tz=tzobj)
        return dt.strftime(fmt)

    except Exception as e:
        # Re-raise with clearer message
        raise RuntimeError("Failed to format timestamp using timestamp_formatter and fallback methods") from e

def extract_domains_geolocation(text: str, timeout: float = 5.0):
    """
    Extract all URLs from `text`, determine each URL's domain, and fetch geolocation
    information for each domain using the url_geo_extractor library's IP API (falls back
    to ip-api.com if the library does not expose an IP lookup function).

    Returns:
      dict mapping domain -> dict with keys:
        - "urls": list of original URLs (unique) that resolved to that domain
        - "geo": geolocation dict returned by the IP API (or {"error": "<message>"} on failure)

    Notes:
      - Requires the url_geo_extractor package. If it's not available the function raises
        ImportError. If the library doesn't provide an IP lookup function, the function
        will call ip-api.com directly (requests required).
      - Example:
          result = extract_domains_geolocation("Visit https://example.com and http://sub.example.com/page")
    """
    # Imports: primary library (required) and fallbacks
    try:
        import url_geo_extractor
    except ImportError as e:
        raise ImportError("Missing dependency: url_geo_extractor. Install with "
                          "'pip install url_geo_extractor'") from e

    from urllib.parse import urlparse
    from collections import defaultdict

    # 1) Extract URLs using the library (expecting a function like extract_urls)
    if not hasattr(url_geo_extractor, "extract_urls"):
        raise AttributeError("url_geo_extractor does not expose extract_urls(text)."
                             " Please check the library version.")
    urls = url_geo_extractor.extract_urls(text) or []

    # 2) Map URLs -> domains (use library get_domain if available, otherwise fallback)
    domain_getter = getattr(url_geo_extractor, "get_domain", None)
    url_to_domain = {}
    for u in urls:
        try:
            if domain_getter:
                domain = domain_getter(u)
            else:
                parsed = urlparse(u if "://" in u else "http://" + u)
                domain = parsed.hostname or parsed.netloc
                if domain and domain.startswith("www."):
                    domain = domain[4:]
            if domain:
                url_to_domain.setdefault(domain.lower(), set()).add(u)
        except Exception:
            # skip malformed URLs
            continue

    # 3) Prepare IP API lookup function from library if available; otherwise fallback to ip-api.com
    ip_lookup_fn = None
    for candidate in ("ip_api", "ip_api_lookup", "ip_lookup", "lookup_ip"):
        if hasattr(url_geo_extractor, candidate):
            ip_lookup_fn = getattr(url_geo_extractor, candidate)
            break

    # If no ip lookup in library, prepare a fallback using requests + ip-api.com
    if ip_lookup_fn is None:
        try:
            import requests
        except ImportError:
            requests = None

        def ip_api_fallback(domain):
            if requests is None:
                raise RuntimeError("url_geo_extractor has no IP lookup function and 'requests' is not installed.")
            # ip-api.com returns JSON at http://ip-api.com/json/<query>
            # we request the full set of fields (no fields query) to be comprehensive
            url = f"http://ip-api.com/json/{domain}"
            try:
                resp = requests.get(url, timeout=timeout)
                resp.raise_for_status()
                return resp.json()
            except Exception as e:
                return {"error": f"ip-api request failed: {str(e)}"}

        ip_lookup_fn = ip_api_fallback

    # 4) Query geolocation for each domain (deduplicated)
    result = {}
    for domain, url_set in url_to_domain.items():
        try:
            # attempt to call ip_lookup_fn(domain, timeout=...) if it accepts timeout
            try:
                geo = ip_lookup_fn(domain, timeout=timeout)
            except TypeError:
                # function might not accept timeout parameter
                geo = ip_lookup_fn(domain)
        except Exception as e:
            geo = {"error": str(e)}
        result[domain] = {
            "urls": sorted(url_set),
            "geo": geo,
        }

    return result

