import re
import csv
from typing import List, Optional

def scrape_emails_to_csv(url: str, csv_path: str, pattern: Optional[str] = None, timeout: int = 10) -> List[str]:
    """
    Scrape the given URL for email addresses using the web_email_scraper library (with a robust fallback)
    and write the results to a CSV file with header "Emails".
    The CSV file is always created even if no emails are found.

    Args:
      url: URL of the page to scrape.
      csv_path: Path to the CSV file to write (will be overwritten if exists).
      pattern: Optional regex pattern to match emails. If None, a sensible default is used.
      timeout: Timeout in seconds to use for HTTP request if the fallback is used.

    Returns:
      A list of unique emails found in the order of appearance (may be empty).
    """
    # Default email regex if none provided
    if pattern is None:
        pattern = r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}'

    emails: List[str] = []

    # Attempt to use the web_email_scraper library if available.
    try:
        import web_email_scraper  # type: ignore
        scraper_used = True

        # Try several common API names for the library
        if hasattr(web_email_scraper, 'extract_emails'):
            try:
                raw = web_email_scraper.extract_emails(url, pattern)
                emails = list(raw) if raw is not None else []
            except TypeError:
                # maybe signature (url,) or (url, pattern, timeout)
                try:
                    raw = web_email_scraper.extract_emails(url)
                    emails = list(raw) if raw is not None else []
                except Exception:
                    emails = []
        elif hasattr(web_email_scraper, 'scrape_emails'):
            try:
                raw = web_email_scraper.scrape_emails(url, pattern)
                emails = list(raw) if raw is not None else []
            except Exception:
                emails = []
        elif hasattr(web_email_scraper, 'get_emails'):
            try:
                raw = web_email_scraper.get_emails(url, pattern)
                emails = list(raw) if raw is not None else []
            except Exception:
                emails = []
        elif hasattr(web_email_scraper, 'WebEmailScraper'):
            try:
                # Try to instantiate and use a commonly named method
                cls = web_email_scraper.WebEmailScraper
                inst = cls(url=url, pattern=pattern)
                if hasattr(inst, 'run'):
                    raw = inst.run()
                elif hasattr(inst, 'scrape'):
                    raw = inst.scrape()
                elif hasattr(inst, 'get_emails'):
                    raw = inst.get_emails()
                else:
                    raw = []
                emails = list(raw) if raw is not None else []
            except Exception:
                emails = []
        else:
            # library present but API unknown -- fall back to manual
            scraper_used = False
    except Exception:
        # import failed or something went wrong: fallback
        scraper_used = False

    # Fallback: manual scraping using requests + re (if we didn't successfully get emails)
    if not scraper_used or emails is None:
        try:
            import requests  # type: ignore
            resp = requests.get(url, timeout=timeout, headers={'User-Agent': 'web-email-scraper/1.0'})
            text = resp.text
        except Exception:
            # If requests not available or request fails, set text empty to ensure CSV is still created
            text = ''

        try:
            found = re.findall(pattern, text, flags=re.IGNORECASE)
            # re.findall may return tuples if the pattern has capture groups; normalize to strings
            normalized = []
            for item in found:
                if isinstance(item, tuple):
                    # choose the first non-empty capture group or join all
                    chosen = next((g for g in item if g), '') or ''.join(item)
                    normalized.append(chosen)
                else:
                    normalized.append(item)
            emails = normalized
        except re.error:
            emails = []

    # Normalize: preserve order, deduplicate, strip whitespace
    seen = set()
    unique_emails: List[str] = []
    for e in emails:
        if e is None:
            continue
        e_str = str(e).strip()
        if not e_str:
            continue
        if e_str not in seen:
            seen.add(e_str)
            unique_emails.append(e_str)

    # Always create the CSV with header "Emails"
    try:
        with open(csv_path, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['Emails'])
            for e in unique_emails:
                writer.writerow([e])
    except Exception as exc:
        # If writing fails, raise to inform caller (CSV creation was requested to always occur;
        # if this fails, it's appropriate to let the caller handle the error).
        raise

    return unique_emails

